package com.example.sleepplayer;

import android.app.AlertDialog;
import android.Manifest;
import android.content.ComponentName;
import android.content.Intent;
import android.content.ServiceConnection;
import android.content.pm.PackageManager;
import android.database.ContentObserver;
import android.media.AudioManager;
import android.net.Uri;
import android.os.Build;
import android.os.Bundle;
import android.os.Handler;
import android.os.IBinder;
import android.os.Looper;
import android.os.StrictMode;
import android.provider.Settings;
import android.view.View;
import android.view.animation.AlphaAnimation;
import android.view.animation.Animation;
import android.widget.AdapterView;
import android.widget.ArrayAdapter;
import android.widget.ImageButton;
import android.widget.ImageView;
import android.widget.PopupMenu;
import android.widget.SeekBar;
import android.widget.Spinner;
import android.widget.TextView;
import android.widget.ProgressBar;
import android.widget.Toast;

import androidx.activity.result.ActivityResultLauncher;
import androidx.activity.result.contract.ActivityResultContracts;
import androidx.annotation.NonNull;
import androidx.appcompat.app.AppCompatActivity;
import androidx.core.content.ContextCompat;
import androidx.recyclerview.widget.LinearLayoutManager;
import androidx.recyclerview.widget.RecyclerView;

import com.google.android.material.materialswitch.MaterialSwitch;
import com.bumptech.glide.Glide;
import com.bumptech.glide.load.resource.drawable.DrawableTransitionOptions;

import java.util.List;
import java.util.Locale;

/**
 * Haupt-Activity für SleepPlayer.
 *
 * Zeigt:
 * - Aktuellen Track (Titel, Künstler)
 * - Play/Pause und Skip-Buttons
 * - Lautstärke-SeekBar (logarithmisch, feine Schritte im leisen Bereich)
 * - Sleep-Timer mit Auswahl und Restzeit-Anzeige
 * - Liste aller verfügbaren Audio-Tracks
 */
public class MainActivity extends AppCompatActivity implements PlaybackService.PlaybackCallback {

    // Timer-Optionen in Minuten
    private static final int[] TIMER_OPTIONS = {5, 10, 15, 20, 30, 45, 60, 90, 120};

    /** Schrittweite pro Hardware-Lautstärketaste (bezogen auf SEEK_BAR_MAX = 200). */
    private static final int VOLUME_KEY_STEP = 4;

    // System-Audio
    private AudioManager audioManager;
    private ContentObserver volumeObserver;
    private int lastSystemVolume = -1;

    // Views
    private TextView tvTrackName;
    private TextView tvTrackArtist;
    private ImageView ivAlbumArt;
    private ImageButton btnPlayPause;
    private ImageButton btnSkip;
    private ImageButton btnRestartTrack;
    private ImageButton btnSettings;
    private MaterialSwitch switchRandom;
    private SeekBar seekVolume;
    private TextView tvVolumePercent;
    private TextView tvVolumeLabel;
    private Spinner spinnerTimer;
    private TextView tvTimerRemaining;
    private ImageButton btnMeditation;
    private TextView tvTrackCount;
    private RecyclerView recyclerTracks;

    // Vollbild-Overlay für Album Art
    private View overlayAlbumArt;
    private ImageView ivAlbumArtFull;

    // Fortschrittsbalken
    private SeekBar seekProgress;
    private TextView tvCurrentPosition;
    private TextView tvTrackDurationLabel;

    /** Handler + Runnable für die sekündliche Fortschritts-Aktualisierung. */
    private final Handler progressHandler = new Handler(Looper.getMainLooper());
    private final Runnable progressRunnable = new Runnable() {
        @Override
        public void run() {
            updateProgress();
            progressHandler.postDelayed(this, 500);
        }
    };

    // Service
    private PlaybackService playbackService;
    private boolean isBound = false;

    /**
     * Aktion die ausgeführt wird sobald der Service verbunden ist.
     * Wird gesetzt wenn der Nutzer Play/Skip drückt bevor der Service bereit ist.
     */
    private Runnable pendingServiceAction = null;

    // Adapter
    private TrackAdapter trackAdapter;

    // Prefs
    private PrefsManager prefsManager;

    // Normalisierung
    private NormalizationStore normalizationStore;

    // Permission Launcher
    private final ActivityResultLauncher<String> requestPermissionLauncher =
            registerForActivityResult(new ActivityResultContracts.RequestPermission(), granted -> {
                if (granted) {
                    loadTracks();
                } else {
                    Toast.makeText(this, R.string.permission_denied, Toast.LENGTH_LONG).show();
                }
            });

    // Notification Permission Launcher
    private final ActivityResultLauncher<String> requestNotificationLauncher =
            registerForActivityResult(new ActivityResultContracts.RequestPermission(), granted -> {
                // Optional, Notification funktioniert auch ohne auf manchen Geräten
            });

    // Ordner-Picker Launcher (SAF = Storage Access Framework)
    private final ActivityResultLauncher<Uri> folderPickerLauncher =
            registerForActivityResult(new ActivityResultContracts.OpenDocumentTree(), uri -> {
                if (uri != null) {
                    onFolderSelected(uri);
                }
            });

    private final ServiceConnection serviceConnection = new ServiceConnection() {
        @Override
        public void onServiceConnected(ComponentName name, IBinder binder) {
            PlaybackService.LocalBinder localBinder = (PlaybackService.LocalBinder) binder;
            playbackService = localBinder.getService();
            isBound = true;

            playbackService.setCallback(MainActivity.this);

            // UI mit aktuellem Zustand synchronisieren
            syncUI();

            // Ausstehende Aktion ausführen (z.B. Play-Druck während Service noch startete)
            if (pendingServiceAction != null) {
                pendingServiceAction.run();
                pendingServiceAction = null;
            }
        }

        @Override
        public void onServiceDisconnected(ComponentName name) {
            playbackService = null;
            isBound = false;
        }
    };

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);

        // StrictMode im Debug-Build: zeigt Main-Thread I/O sofort im Logcat
        if (BuildConfig.DEBUG) {
            StrictMode.setThreadPolicy(new StrictMode.ThreadPolicy.Builder()
                    .detectDiskReads()
                    .detectDiskWrites()
                    .penaltyLog()
                    .build());
        }

        setContentView(R.layout.activity_main);

        prefsManager = new PrefsManager(this);
        normalizationStore = new NormalizationStore(this);
        audioManager = (AudioManager) getSystemService(AUDIO_SERVICE);

        // Lautstärketasten sollen den Medien-Stream steuern
        setVolumeControlStream(AudioManager.STREAM_MUSIC);

        initViews();
        setupVolumeControl();
        setupTimerSpinner();
        setupRandomSwitch();
        setupSettingsButton();
        setupTrackList();
        checkPermissions();
    }

    @Override
    protected void onStart() {
        super.onStart();
        // An den Service binden (falls er läuft)
        Intent intent = new Intent(this, PlaybackService.class);
        bindService(intent, serviceConnection, 0);
    }

    @Override
    protected void onResume() {
        super.onResume();
        registerVolumeObserver();
        // Fortschrittsbalken starten falls gerade abgespielt wird
        if (isBound && playbackService != null && playbackService.isPlaying()) {
            progressHandler.post(progressRunnable);
        }
    }

    @Override
    protected void onPause() {
        super.onPause();
        unregisterVolumeObserver();
        progressHandler.removeCallbacks(progressRunnable);
    }

    @Override
    protected void onStop() {
        super.onStop();
        pendingServiceAction = null; // ausstehende Aktionen verwerfen
        if (isBound) {
            if (playbackService != null) {
                playbackService.setCallback(null);
            }
            unbindService(serviceConnection);
            isBound = false;
        }
    }

    /**
     * ContentObserver für Systemlautstärke-Änderungen.
     * Funktioniert auch wenn die MediaSession die Tasten abfängt.
     * Erkennt die Richtung der Änderung und verschiebt den in-app Slider
     * um VOLUME_KEY_STEP – so bleibt die logarithmische Feinregelung erhalten.
     */
    private void registerVolumeObserver() {
        lastSystemVolume = audioManager.getStreamVolume(AudioManager.STREAM_MUSIC);
        volumeObserver = new ContentObserver(new Handler(Looper.getMainLooper())) {
            @Override
            public void onChange(boolean selfChange) {
                int newSystemVolume = audioManager.getStreamVolume(AudioManager.STREAM_MUSIC);
                if (newSystemVolume == lastSystemVolume) return;

                boolean volumeUp = newSystemVolume > lastSystemVolume;
                lastSystemVolume = newSystemVolume;

                int current = seekVolume.getProgress();
                int next = volumeUp
                        ? Math.min(VolumeHelper.SEEK_BAR_MAX, current + VOLUME_KEY_STEP)
                        : Math.max(0, current - VOLUME_KEY_STEP);

                if (next != current) {
                    seekVolume.setProgress(next);
                    updateVolumeLabel(next);
                    float volume = VolumeHelper.progressToVolume(next);
                    if (isBound && playbackService != null) {
                        playbackService.setVolume(volume);
                    }
                    prefsManager.saveVolume(next);
                }
            }
        };
        getContentResolver().registerContentObserver(
                Settings.System.CONTENT_URI, true, volumeObserver);
    }

    private void unregisterVolumeObserver() {
        if (volumeObserver != null) {
            getContentResolver().unregisterContentObserver(volumeObserver);
            volumeObserver = null;
        }
    }

    // ===== Initialisierung =====

    private void initViews() {
        tvTrackName = findViewById(R.id.tvTrackName);
        tvTrackArtist = findViewById(R.id.tvTrackArtist);
        ivAlbumArt = findViewById(R.id.ivAlbumArt);
        btnPlayPause = findViewById(R.id.btnPlayPause);
        btnSkip = findViewById(R.id.btnSkip);
        btnRestartTrack = findViewById(R.id.btnRestartTrack);
        btnSettings = findViewById(R.id.btnSettings);
        switchRandom = findViewById(R.id.switchRandom);
        seekVolume = findViewById(R.id.seekVolume);
        tvVolumePercent = findViewById(R.id.tvVolumePercent);
        tvVolumeLabel = findViewById(R.id.tvVolumeLabel);
        spinnerTimer = findViewById(R.id.spinnerTimer);
        tvTimerRemaining = findViewById(R.id.tvTimerRemaining);
        btnMeditation = findViewById(R.id.btnMeditation);
        tvTrackCount = findViewById(R.id.tvTrackCount);
        recyclerTracks = findViewById(R.id.recyclerTracks);
        overlayAlbumArt = findViewById(R.id.overlayAlbumArt);
        ivAlbumArtFull = findViewById(R.id.ivAlbumArtFull);
        seekProgress = findViewById(R.id.seekProgress);
        tvCurrentPosition = findViewById(R.id.tvCurrentPosition);
        tvTrackDurationLabel = findViewById(R.id.tvTrackDurationLabel);

        btnPlayPause.setOnClickListener(v -> onPlayPauseClicked());
        btnSkip.setOnClickListener(v -> onSkipClicked());
        btnRestartTrack.setOnClickListener(v -> onRestartTrackClicked());

        // Meditations-Button: togglet die 4-7-8 Atemübung (wie Doppelklick am Kopfhörer)
        btnMeditation.setOnClickListener(v -> {
            ensureServiceStarted();
            if (isBound && playbackService != null) {
                playbackService.toggleMeditation();
            } else {
                pendingServiceAction = () -> playbackService.toggleMeditation();
            }
        });

        // Klick auf kleines Album-Art → Vollbild-Overlay öffnen
        ivAlbumArt.setOnClickListener(v -> showAlbumArtOverlay());

        // Klick irgendwo im Overlay → schließen
        overlayAlbumArt.setOnClickListener(v -> hideAlbumArtOverlay());

        // Fortschrittsbalken: Nutzer kann Position manuell setzen
        seekProgress.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener() {
            @Override public void onProgressChanged(SeekBar s, int p, boolean fromUser) {}
            @Override public void onStartTrackingTouch(SeekBar s) {
                // Aktualisierung pausieren während der Nutzer zieht
                progressHandler.removeCallbacks(progressRunnable);
            }
            @Override public void onStopTrackingTouch(SeekBar s) {
                if (isBound && playbackService != null) {
                    int duration = playbackService.getDuration();
                    if (duration > 0) {
                        int seekMs = (int) ((long) s.getProgress() * duration / 1000);
                        playbackService.seekTo(seekMs);
                    }
                }
                // Aktualisierung wieder starten
                progressHandler.post(progressRunnable);
            }
        });
    }

    private void setupVolumeControl() {
        seekVolume.setMax(VolumeHelper.SEEK_BAR_MAX);

        // Gespeicherten Wert laden
        int savedProgress = prefsManager.getVolume();
        seekVolume.setProgress(savedProgress);
        updateVolumeLabel(savedProgress);

        seekVolume.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener() {
            @Override
            public void onProgressChanged(SeekBar seekBar, int progress, boolean fromUser) {
                if (fromUser) {
                    float volume = VolumeHelper.progressToVolume(progress);
                    if (isBound && playbackService != null) {
                        playbackService.setVolume(volume);
                    }
                    updateVolumeLabel(progress);
                    prefsManager.saveVolume(progress);
                }
            }

            @Override
            public void onStartTrackingTouch(SeekBar seekBar) {}

            @Override
            public void onStopTrackingTouch(SeekBar seekBar) {}
        });
    }

    private void updateVolumeLabel(int progress) {
        int percent = VolumeHelper.progressToPercent(progress);
        tvVolumePercent.setText(String.format(Locale.getDefault(), "%d%%", percent));
        tvVolumeLabel.setText(String.format(Locale.getDefault(),
                getString(R.string.volume_label), percent));
    }

    private void setupTimerSpinner() {
        String[] timerLabels = new String[TIMER_OPTIONS.length];
        for (int i = 0; i < TIMER_OPTIONS.length; i++) {
            timerLabels[i] = TIMER_OPTIONS[i] + " " + getString(R.string.minutes_suffix);
        }

        ArrayAdapter<String> adapter = new ArrayAdapter<>(this,
                android.R.layout.simple_spinner_item, timerLabels);
        adapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);
        spinnerTimer.setAdapter(adapter);

        // Gespeicherten Wert auswählen
        int savedMinutes = prefsManager.getTimerMinutes();
        for (int i = 0; i < TIMER_OPTIONS.length; i++) {
            if (TIMER_OPTIONS[i] == savedMinutes) {
                spinnerTimer.setSelection(i);
                break;
            }
        }

        spinnerTimer.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener() {
            @Override
            public void onItemSelected(AdapterView<?> parent, View view, int pos, long id) {
                int minutes = TIMER_OPTIONS[pos];
                prefsManager.saveTimerMinutes(minutes);
                if (isBound && playbackService != null && playbackService.isTimerRunning()) {
                    // Timer mit neuer Dauer neu starten
                    playbackService.startTimer(minutes);
                }
            }

            @Override
            public void onNothingSelected(AdapterView<?> parent) {}
        });
    }

    private void setupTrackList() {
        trackAdapter = new TrackAdapter();
        trackAdapter.setNormalizationStore(normalizationStore);
        recyclerTracks.setLayoutManager(new LinearLayoutManager(this));
        recyclerTracks.setAdapter(trackAdapter);

        trackAdapter.setOnTrackClickListener(track -> {
            ensureServiceStarted();
            if (isBound && playbackService != null) {
                playbackService.playTrack(track);
            } else {
                pendingServiceAction = () -> playbackService.playTrack(track);
            }
        });

        // Longpress → Referenz-Track setzen
        trackAdapter.setOnTrackLongClickListener(track -> showReferenceTrackMenu(track));
    }

    private void setupRandomSwitch() {
        // Gespeicherten Modus laden
        boolean savedRandom = prefsManager.isRandomMode();
        switchRandom.setChecked(savedRandom);
        switchRandom.setText(savedRandom ? R.string.mode_random : R.string.mode_sequential);

        switchRandom.setOnCheckedChangeListener((button, isChecked) -> {
            prefsManager.saveRandomMode(isChecked);
            button.setText(isChecked ? R.string.mode_random : R.string.mode_sequential);
            if (isBound && playbackService != null) {
                playbackService.setRandomMode(isChecked);
            }
        });
    }

    // ===== Settings-Button / Ordner-Auswahl =====

    private void setupSettingsButton() {
        btnSettings.setOnClickListener(v -> showSettingsMenu());
    }

    /**
     * Zeigt ein PopupMenu mit Ordner-Auswahl-Optionen, TTS-Toggle und Normalisierung.
     */
    private void showSettingsMenu() {
        PopupMenu popup = new PopupMenu(this, btnSettings);

        // Aktuellen Ordner als erstes (deaktiviertes) Item anzeigen
        String folderName = prefsManager.getFolderDisplayName();
        String folderLabel = (folderName != null)
                ? getString(R.string.settings_folder_title) + ": " + folderName
                : getString(R.string.settings_folder_title) + ": " + getString(R.string.folder_all);
        popup.getMenu().add(0, 0, 0, folderLabel).setEnabled(false);
        popup.getMenu().add(0, 1, 1, getString(R.string.settings_folder_select));
        popup.getMenu().add(0, 2, 2, getString(R.string.settings_folder_clear))
                .setEnabled(folderName != null);

        // TTS-Toggle
        boolean ttsEnabled = prefsManager.isTtsEnabled();
        popup.getMenu().add(0, 3, 3,
                ttsEnabled ? getString(R.string.tts_on) : getString(R.string.tts_off));

        // Normalisierung – "Normalisieren" immer aktiv (zeigt eigene Hinweise wenn nötig),
        // "Zurücksetzen" nur aktiv wenn überhaupt Gain-Daten vorhanden
        popup.getMenu().add(0, 4, 4, getString(R.string.norm_menu_normalize))
                .setEnabled(true);
        popup.getMenu().add(0, 5, 5, getString(R.string.norm_menu_reset))
                .setEnabled(!normalizationStore.getAllGains().isEmpty());

        // Referenz-Info (deaktiviert, nur zur Info)
        String refTitle = normalizationStore.getReferenceTrackTitle();
        if (refTitle != null) {
            popup.getMenu().add(0, 6, 6, "⭐ " + getString(R.string.norm_ref_label) + ": " + refTitle)
                    .setEnabled(false);
        } else {
            popup.getMenu().add(0, 6, 6, getString(R.string.norm_ref_hint))
                    .setEnabled(false);
        }

        popup.setOnMenuItemClickListener(item -> {
            switch (item.getItemId()) {
                case 1:
                    folderPickerLauncher.launch(null);
                    return true;
                case 2:
                    prefsManager.clearFolder();
                    loadTracks();
                    Toast.makeText(this, R.string.folder_all, Toast.LENGTH_SHORT).show();
                    return true;
                case 3:
                    boolean newTts = !prefsManager.isTtsEnabled();
                    prefsManager.saveTtsEnabled(newTts);
                    Toast.makeText(this,
                            newTts ? R.string.tts_on : R.string.tts_off,
                            Toast.LENGTH_SHORT).show();
                    return true;
                case 4:
                    startNormalization();
                    return true;
                case 5:
                    normalizationStore.clearGains();   // Nur Gains löschen, Referenz-Track bleibt erhalten
                    trackAdapter.notifyDataSetChanged();
                    Toast.makeText(this, R.string.norm_reset_done, Toast.LENGTH_SHORT).show();
                    return true;
            }
            return false;
        });
        popup.show();
    }

    /**
     * Zeigt ein Kontextmenü zum Setzen des Referenz-Tracks und Normalisierungsoptionen (nach Longpress).
     */
    private void showReferenceTrackMenu(TrackSelector.TrackInfo track) {
        boolean hasSectional = normalizationStore.hasSectionalGains(track.uri.toString());
        java.util.List<String> items = new java.util.ArrayList<>();
        items.add(getString(R.string.norm_set_ref_confirm));
        items.add(getString(R.string.norm_single_track));
        items.add(getString(R.string.norm_sectional));
        if (hasSectional) {
            items.add(getString(R.string.norm_sectional_visualize));
            items.add(getString(R.string.norm_sectional_clear));
        }

        new AlertDialog.Builder(this)
                .setTitle(track.title)
                .setItems(items.toArray(new String[0]), (d, which) -> {
                    String chosen = items.get(which);
                    if (chosen.equals(getString(R.string.norm_set_ref_confirm))) {
                        normalizationStore.saveReferenceTrack(track.uri.toString(), track.title);
                        trackAdapter.notifyDataSetChanged();
                        Toast.makeText(this, getString(R.string.norm_ref_set, track.title), Toast.LENGTH_SHORT).show();
                    } else if (chosen.equals(getString(R.string.norm_single_track))) {
                        startSingleTrackNormalization(track);
                    } else if (chosen.equals(getString(R.string.norm_sectional))) {
                        startSectionalNormalization(track);
                    } else if (chosen.equals(getString(R.string.norm_sectional_visualize))) {
                        showSectionalGainChart(track);
                    } else if (chosen.equals(getString(R.string.norm_sectional_clear))) {
                        normalizationStore.clearSectionalGains(track.uri.toString());
                        trackAdapter.notifyDataSetChanged();
                        Toast.makeText(this, getString(R.string.norm_reset_done), Toast.LENGTH_SHORT).show();
                    }
                })
                .setNegativeButton(android.R.string.cancel, null)
                .show();
    }

    /**
     * Zeigt ein Diagramm der sektionsweisen Gain-Anpassungen für einen Track.
     * Grüne Balken = leise Stellen werden angehoben, orange = laute werden gedämpft.
     * Eine pinke Linie zeigt die aktuelle Wiedergabeposition (falls dieser Track spielt).
     */
    private void showSectionalGainChart(TrackSelector.TrackInfo track) {
        java.util.List<float[]> sections = normalizationStore.getSectionalGains(track.uri.toString());
        if (sections == null || sections.isEmpty()) {
            Toast.makeText(this, R.string.norm_no_tracks, Toast.LENGTH_SHORT).show();
            return;
        }

        SectionalGainChartView chartView = new SectionalGainChartView(this);
        chartView.setSections(sections);

        // Aktuelle Wiedergabeposition eintragen, falls dieser Track gerade spielt
        if (isBound && playbackService != null && playbackService.getCurrentTrack() != null
                && playbackService.getCurrentTrack().uri.toString().equals(track.uri.toString())) {
            chartView.setCurrentPosition(playbackService.getCurrentPosition());
        }

        // Höhe: 260dp
        int heightPx = (int)(260 * getResources().getDisplayMetrics().density);
        chartView.setMinimumHeight(heightPx);

        // Zusammenfassung unter dem Diagramm
        int boostCount = 0, cutCount = 0, neutralCount = 0;
        float maxBoostDb = 0f, maxCutDb = 0f;
        for (float[] s : sections) {
            float db = (float)(20.0 * Math.log10(Math.max(1e-6, s[1])));
            if (db > 0.5f) { boostCount++; maxBoostDb = Math.max(maxBoostDb, db); }
            else if (db < -0.5f) { cutCount++; maxCutDb = Math.max(maxCutDb, -db); }
            else neutralCount++;
        }
        String summary = String.format(Locale.getDefault(),
                "%d Sektionen  •  ▲ %d angehoben (max +%.1fdB)  •  ▼ %d gedämpft (max −%.1fdB)  •  %d neutral",
                sections.size(), boostCount, maxBoostDb, cutCount, maxCutDb, neutralCount);

        android.widget.LinearLayout layout = new android.widget.LinearLayout(this);
        layout.setOrientation(android.widget.LinearLayout.VERTICAL);
        layout.addView(chartView);

        TextView summaryView = new TextView(this);
        summaryView.setText(summary);
        summaryView.setTextColor(0xFF90A4AE);
        summaryView.setTextSize(11f);
        int pad = (int)(12 * getResources().getDisplayMetrics().density);
        summaryView.setPadding(pad, pad/2, pad, pad);
        layout.addView(summaryView);

        new AlertDialog.Builder(this)
                .setTitle(getString(R.string.norm_sectional_chart_title) + "\n" + track.title)
                .setView(layout)
                .setPositiveButton(android.R.string.ok, null)
                // "Neu analysieren" Shortcut
                .setNeutralButton(getString(R.string.norm_sectional), (d, w) -> startSectionalNormalization(track))
                .show();
    }

    /**
     * Normalisiert einen einzelnen Track gegen den Referenz-Track.
     */
    private void startSingleTrackNormalization(TrackSelector.TrackInfo track) {
        String refUri = normalizationStore.getReferenceTrackUri();
        if (refUri == null) {
            new AlertDialog.Builder(this)
                    .setTitle(getString(R.string.norm_menu_normalize))
                    .setMessage(getString(R.string.norm_no_ref))
                    .setPositiveButton(android.R.string.ok, null).show();
            return;
        }

        // Fortschritts-Dialog
        android.widget.ProgressBar pb = new android.widget.ProgressBar(this, null,
                android.R.attr.progressBarStyleHorizontal);
        pb.setMax(100);
        int pad = (int)(16 * getResources().getDisplayMetrics().density);
        pb.setPadding(pad, pad, pad, pad);
        AlertDialog dlg = new AlertDialog.Builder(this)
                .setTitle(R.string.norm_progress_title)
                .setMessage(track.title)
                .setView(pb)
                .setCancelable(false)
                .create();
        dlg.show();

        new Thread(() -> {
            // Referenz-RMS
            float refDb = Float.NaN;
            if (track.uri.toString().equals(refUri)) {
                refDb = AudioAnalyzer.analyzeRmsDb(this, track.uri, p -> runOnUiThread(() -> pb.setProgress(p)));
            } else {
                // Analyse der Referenz (schnell, nur 60s)
                TrackSelector selector = isBound && playbackService != null
                        ? playbackService.getTrackSelector() : new TrackSelector(this);
                for (TrackSelector.TrackInfo t : selector.getAllTracks()) {
                    if (t.uri.toString().equals(refUri)) {
                        refDb = AudioAnalyzer.analyzeRmsDb(this, t.uri);
                        break;
                    }
                }
                if (Float.isNaN(refDb)) {
                    runOnUiThread(() -> { dlg.dismiss();
                        Toast.makeText(this, R.string.norm_ref_analysis_failed, Toast.LENGTH_LONG).show(); });
                    return;
                }
                float trackDb = AudioAnalyzer.analyzeRmsDb(this, track.uri,
                        p -> runOnUiThread(() -> pb.setProgress(p)));
                if (Float.isNaN(trackDb)) {
                    runOnUiThread(() -> { dlg.dismiss();
                        Toast.makeText(this, R.string.norm_track_analysis_failed, Toast.LENGTH_LONG).show(); });
                    return;
                }
                float gain = NormalizationStore.computeGainMultiplier(refDb, trackDb);
                normalizationStore.saveGain(track.uri.toString(), gain);
                String gainStr = String.format(java.util.Locale.getDefault(), "%.2f", gain);
                runOnUiThread(() -> { dlg.dismiss(); trackAdapter.notifyDataSetChanged();
                    Toast.makeText(this, getString(R.string.norm_single_done, gainStr), Toast.LENGTH_LONG).show(); });
                return;
            }
            // Track ist selbst der Referenz-Track → Gain 1.0
            normalizationStore.saveGain(track.uri.toString(), 1.0f);
            runOnUiThread(() -> { dlg.dismiss(); trackAdapter.notifyDataSetChanged();
                Toast.makeText(this, getString(R.string.norm_single_done, "1.00"), Toast.LENGTH_SHORT).show(); });
        }, "SingleNormThread").start();
    }

    /**
     * Sektionsweise Normalisierung für einen einzelnen Track.
     * Analysiert den Track in 30-Sekunden-Abschnitten und speichert pro Abschnitt einen Gain.
     */
    private void startSectionalNormalization(TrackSelector.TrackInfo track) {
        String refUri = normalizationStore.getReferenceTrackUri();
        if (refUri == null) {
            new AlertDialog.Builder(this)
                    .setTitle(getString(R.string.norm_menu_normalize))
                    .setMessage(getString(R.string.norm_no_ref))
                    .setPositiveButton(android.R.string.ok, null).show();
            return;
        }

        android.widget.ProgressBar pb = new android.widget.ProgressBar(this, null,
                android.R.attr.progressBarStyleHorizontal);
        pb.setMax(100);
        int pad = (int)(16 * getResources().getDisplayMetrics().density);
        pb.setPadding(pad, pad, pad, pad);
        AlertDialog dlg = new AlertDialog.Builder(this)
                .setTitle(R.string.norm_sectional_title)
                .setMessage(track.title)
                .setView(pb)
                .setCancelable(false)
                .create();
        dlg.show();

        new Thread(() -> {
            // Referenz-RMS (Gesamtlevel als Ziel)
            float refDb = Float.NaN;
            TrackSelector selector = isBound && playbackService != null
                    ? playbackService.getTrackSelector() : new TrackSelector(this);
            for (TrackSelector.TrackInfo t : selector.getAllTracks()) {
                if (t.uri.toString().equals(refUri)) {
                    refDb = AudioAnalyzer.analyzeRmsDb(this, t.uri);
                    break;
                }
            }
            if (Float.isNaN(refDb)) {
                final float finalRefDb = refDb;
                runOnUiThread(() -> { dlg.dismiss();
                    Toast.makeText(this, R.string.norm_ref_analysis_failed, Toast.LENGTH_LONG).show(); });
                return;
            }

            final float targetDb = refDb;
            // Sektionsweise Analyse des Tracks (30-Sekunden-Fenster)
            java.util.List<float[]> sections = AudioAnalyzer.analyzeSectionsDb(
                    this, track.uri, 30_000,
                    p -> runOnUiThread(() -> pb.setProgress(p)));

            if (sections.isEmpty()) {
                runOnUiThread(() -> { dlg.dismiss();
                    Toast.makeText(this, R.string.norm_track_analysis_failed, Toast.LENGTH_LONG).show(); });
                return;
            }

            // Für jede Sektion Gain berechnen: [startMs, gainMul]
            java.util.List<float[]> sectionalGains = new java.util.ArrayList<>();
            for (float[] s : sections) {
                float sectionDb = s[1];
                float gain = Float.isNaN(sectionDb) || sectionDb <= -99f
                        ? 1.0f
                        : NormalizationStore.computeGainMultiplier(targetDb, sectionDb);
                // Auf ±18 dB begrenzen
                float maxMul = (float) Math.pow(10, NormalizationStore.MAX_GAIN_DB / 20f);
                gain = Math.max(1f / maxMul, Math.min(maxMul, gain));
                sectionalGains.add(new float[]{s[0], gain});
            }

            normalizationStore.saveSectionalGains(track.uri.toString(), sectionalGains);
            final int count = sectionalGains.size();
            runOnUiThread(() -> { dlg.dismiss(); trackAdapter.notifyDataSetChanged();
                Toast.makeText(this, getString(R.string.norm_sectional_done, count), Toast.LENGTH_LONG).show(); });
        }, "SectionalNormThread").start();
    }

    /**
     * Startet die Normalisierungs-Analyse für alle Tracks im Hintergrund.
     * Zeigt einen Fortschritts-Dialog und speichert die Gains danach.
     */
    private void startNormalization() {
        // Track-Liste holen (bereits geladen im Adapter)
        List<TrackSelector.TrackInfo> allTracks;
        try {
            // Tracks via TrackSelector neu laden (sicher, eigener Thread folgt)
            TrackSelector selector = isBound && playbackService != null
                    ? playbackService.getTrackSelector()
                    : new TrackSelector(this);
            allTracks = selector.getAllTracks();
        } catch (Exception e) {
            Toast.makeText(this, R.string.norm_no_tracks, Toast.LENGTH_SHORT).show();
            return;
        }
        if (allTracks.isEmpty()) {
            Toast.makeText(this, R.string.norm_no_tracks, Toast.LENGTH_SHORT).show();
            return;
        }

        String refUri = normalizationStore.getReferenceTrackUri();
        if (refUri == null) {
            // Kein Referenz-Track → erklärenden Dialog zeigen
            new AlertDialog.Builder(this)
                    .setTitle(getString(R.string.norm_menu_normalize))
                    .setMessage(getString(R.string.norm_no_ref))
                    .setPositiveButton(android.R.string.ok, null)
                    .show();
            return;
        }

        // Fortschritts-Dialog aufbauen
        ProgressBar progressBar = new ProgressBar(this, null, android.R.attr.progressBarStyleHorizontal);
        progressBar.setMax(allTracks.size());
        progressBar.setProgress(0);
        int padding = (int) (16 * getResources().getDisplayMetrics().density);
        progressBar.setPadding(padding, padding, padding, padding);

        AlertDialog progressDialog = new AlertDialog.Builder(this)
                .setTitle(R.string.norm_progress_title)
                .setMessage(getString(R.string.norm_progress_msg, 0, allTracks.size()))
                .setView(progressBar)
                .setCancelable(false)
                .create();
        progressDialog.show();

        // Analyse im Hintergrund
        new Thread(() -> {
            // 1) Referenz-RMS berechnen
            TrackSelector.TrackInfo refTrack = null;
            for (TrackSelector.TrackInfo t : allTracks) {
                if (t.uri.toString().equals(refUri)) {
                    refTrack = t;
                    break;
                }
            }
            if (refTrack == null) {
                runOnUiThread(() -> {
                    progressDialog.dismiss();
                    Toast.makeText(this, R.string.norm_ref_not_found, Toast.LENGTH_LONG).show();
                });
                return;
            }

            float refDb = AudioAnalyzer.analyzeRmsDb(this, refTrack.uri);
            if (Float.isNaN(refDb)) {
                runOnUiThread(() -> {
                    progressDialog.dismiss();
                    Toast.makeText(this, R.string.norm_ref_analysis_failed, Toast.LENGTH_LONG).show();
                });
                return;
            }

            // 2) Alle anderen Tracks analysieren
            int analyzed = 0;
            int failed = 0;
            final int total = allTracks.size();

            for (TrackSelector.TrackInfo track : allTracks) {
                analyzed++;
                final int progress = analyzed;

                runOnUiThread(() -> {
                    progressBar.setProgress(progress);
                    progressDialog.setMessage(
                            getString(R.string.norm_progress_msg, progress, total));
                });

                String trackUri = track.uri.toString();
                if (trackUri.equals(refUri)) {
                    // Referenz selbst bekommt Gain 1.0
                    normalizationStore.saveGain(trackUri, 1.0f);
                    continue;
                }

                float trackDb = AudioAnalyzer.analyzeRmsDb(this, track.uri);
                if (Float.isNaN(trackDb)) {
                    failed++;
                    android.util.Log.w("MainActivity", "Analyse fehlgeschlagen: " + track.title);
                    continue;
                }

                float gain = NormalizationStore.computeGainMultiplier(refDb, trackDb);
                normalizationStore.saveGain(trackUri, gain);
            }

            final int finalFailed = failed;
            runOnUiThread(() -> {
                progressDialog.dismiss();
                trackAdapter.notifyDataSetChanged();
                String msg = getString(R.string.norm_done, total - finalFailed, total);
                if (finalFailed > 0) {
                    msg += " (" + getString(R.string.norm_failed_count, finalFailed) + ")";
                }
                Toast.makeText(this, msg, Toast.LENGTH_LONG).show();
            });

        }, "NormalizationThread").start();
    }

    /**
     * Wird aufgerufen wenn der Benutzer einen Ordner ausgewählt hat.
     */
    private void onFolderSelected(Uri treeUri) {
        String displayName = extractFolderDisplayName(treeUri);
        prefsManager.saveFolderUri(treeUri.toString());
        prefsManager.saveFolderDisplayName(displayName);
        loadTracks();
        Toast.makeText(this, getString(R.string.settings_folder_title) + ": " + displayName,
                Toast.LENGTH_SHORT).show();
    }

    /**
     * Extrahiert einen lesbaren Ordnernamen aus einem SAF Tree-URI.
     * z.B. "content://...externalstorage.../tree/primary%3AMusic%2FSleep"
     *  → "Music/Sleep"
     */
    private String extractFolderDisplayName(Uri treeUri) {
        String path = treeUri.getPath();
        if (path != null && path.startsWith("/tree/")) {
            String docId = path.substring(6); // nach "/tree/"
            // docId: "primary:Music/Sleep" oder "XXXX-XXXX:Folder"
            int colonIndex = docId.indexOf(':');
            if (colonIndex >= 0 && colonIndex < docId.length() - 1) {
                return docId.substring(colonIndex + 1);
            }
        }
        // Fallback: letztes Segment des URI
        return treeUri.getLastPathSegment();
    }

    // ===== Permissions =====

    private void checkPermissions() {
        // Audio Permission
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
            if (ContextCompat.checkSelfPermission(this, Manifest.permission.READ_MEDIA_AUDIO)
                    != PackageManager.PERMISSION_GRANTED) {
                requestPermissionLauncher.launch(Manifest.permission.READ_MEDIA_AUDIO);
            } else {
                loadTracks();
            }
        } else {
            if (ContextCompat.checkSelfPermission(this, Manifest.permission.READ_EXTERNAL_STORAGE)
                    != PackageManager.PERMISSION_GRANTED) {
                requestPermissionLauncher.launch(Manifest.permission.READ_EXTERNAL_STORAGE);
            } else {
                loadTracks();
            }
        }

        // Notification Permission (API 33+)
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
            if (ContextCompat.checkSelfPermission(this, Manifest.permission.POST_NOTIFICATIONS)
                    != PackageManager.PERMISSION_GRANTED) {
                requestNotificationLauncher.launch(Manifest.permission.POST_NOTIFICATIONS);
            }
        }
    }

    private void loadTracks() {
        // MediaStore-Query im Hintergrund laden (kein Main-Thread I/O)
        new Thread(() -> {
            TrackSelector selector = new TrackSelector(this);
            selector.clearCache();
            List<TrackSelector.TrackInfo> tracks = selector.getAllTracks();
            runOnUiThread(() -> {
                trackAdapter.setTracks(tracks);
                tvTrackCount.setText(String.format(Locale.getDefault(),
                        getString(R.string.tracks_found), tracks.size()));
                if (tracks.isEmpty()) {
                    tvTrackName.setText(R.string.no_audio_files);
                } else {
                    // Zufälligen Track vorauswählen und im UI anzeigen,
                    // falls gerade nichts spielt – so sieht der Nutzer sofort
                    // welcher Track beim ersten Play-Druck gestartet wird.
                    boolean nothingPlaying = !isBound
                            || playbackService == null
                            || playbackService.getCurrentTrack() == null;
                    if (nothingPlaying) {
                        int idx = (int) (Math.random() * tracks.size());
                        TrackSelector.TrackInfo preselected = tracks.get(idx);
                        tvTrackName.setText(preselected.title);
                        tvTrackArtist.setText(preselected.artist);
                        updateAlbumArt(preselected);
                    }
                }
            });
        }, "LoadTracks").start();
    }

    // ===== Playback Controls =====

    private void onPlayPauseClicked() {
        ensureServiceStarted();
        if (isBound && playbackService != null) {
            playbackService.togglePlayPause();
        } else {
            // Service startet gerade async – Aktion merken und in onServiceConnected ausführen
            pendingServiceAction = () -> playbackService.togglePlayPause();
        }
    }

    private void onSkipClicked() {
        ensureServiceStarted();
        if (isBound && playbackService != null) {
            playbackService.skipToNext();
        } else {
            pendingServiceAction = () -> playbackService.skipToNext();
        }
    }

    /** Setzt den aktuellen Titel auf Position 0 zurück (Anfang des Tracks). */
    private void onRestartTrackClicked() {
        ensureServiceStarted();
        if (isBound && playbackService != null) {
            playbackService.seekTo(0);
        } else {
            pendingServiceAction = () -> playbackService.seekTo(0);
        }
    }

    /**
     * Stellt sicher, dass der Service gestartet und gebunden ist.
     */
    private void ensureServiceStarted() {
        Intent intent = new Intent(this, PlaybackService.class);
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            startForegroundService(intent);
        } else {
            startService(intent);
        }

        if (!isBound) {
            bindService(intent, serviceConnection, BIND_AUTO_CREATE);
        }
    }

    // ===== PlaybackCallback Implementierung =====

    @Override
    public void onTrackChanged(TrackSelector.TrackInfo track) {
        runOnUiThread(() -> {
            if (track != null) {
                tvTrackName.setText(track.title);
                tvTrackArtist.setText(track.artist);
                updateAlbumArt(track);
            }
            // Fortschritt zurücksetzen bis die neue Position eintrifft
            seekProgress.setProgress(0);
            tvCurrentPosition.setText("0:00");
            tvTrackDurationLabel.setText(formatMs(track != null ? track.duration : 0));
        });
    }

    @Override
    public void onPlaybackStateChanged(boolean isPlaying) {
        runOnUiThread(() -> {
            btnPlayPause.setImageResource(isPlaying ? R.drawable.ic_pause : R.drawable.ic_play);
            btnPlayPause.setContentDescription(getString(isPlaying ? R.string.pause : R.string.play));
            if (isPlaying) {
                progressHandler.post(progressRunnable);
            } else {
                progressHandler.removeCallbacks(progressRunnable);
            }
        });
    }

    @Override
    public void onTimerTick(long millisRemaining) {
        runOnUiThread(() -> {
            tvTimerRemaining.setText(formatTime(millisRemaining));
        });
    }

    @Override
    public void onTimerFinished() {
        runOnUiThread(() -> {
            tvTimerRemaining.setText(R.string.timer_off);
            btnPlayPause.setImageResource(R.drawable.ic_play);
            btnPlayPause.setContentDescription(getString(R.string.play));
        });
    }

    @Override
    public void onMeditationStateChanged(boolean active,
            MeditationController.Phase phase, int cycle) {
        runOnUiThread(() -> {
            if (active) {
                // Meditation aktiv: voll sichtbar + türkis eingefärbt
                btnMeditation.setAlpha(1.0f);
                btnMeditation.setColorFilter(
                        ContextCompat.getColor(this, R.color.teal_200),
                        android.graphics.PorterDuff.Mode.SRC_IN);
            } else {
                // Meditation inaktiv: gedimmt + keine Färbung
                btnMeditation.setAlpha(0.6f);
                btnMeditation.clearColorFilter();
            }
            btnMeditation.setContentDescription(
                    getString(active ? R.string.meditation_stop : R.string.meditation_start));
        });
    }

    // ===== UI Sync =====

    private void syncUI() {
        if (!isBound || playbackService == null) return;

        // Aktuellen Track anzeigen
        TrackSelector.TrackInfo track = playbackService.getCurrentTrack();
        if (track != null) {
            tvTrackName.setText(track.title);
            tvTrackArtist.setText(track.artist);
            updateAlbumArt(track);
        }

        // Play/Pause Button
        boolean playing = playbackService.isPlaying();
        btnPlayPause.setImageResource(playing ? R.drawable.ic_pause : R.drawable.ic_play);

        // Random Switch mit Service-Zustand synchronisieren
        boolean random = playbackService.isRandomMode();
        switchRandom.setOnCheckedChangeListener(null); // Listener kurz deaktivieren
        switchRandom.setChecked(random);
        switchRandom.setText(random ? R.string.mode_random : R.string.mode_sequential);
        switchRandom.setOnCheckedChangeListener((button, isChecked) -> {
            prefsManager.saveRandomMode(isChecked);
            button.setText(isChecked ? R.string.mode_random : R.string.mode_sequential);
            if (isBound && playbackService != null) {
                playbackService.setRandomMode(isChecked);
            }
        });

        // Timer
        if (playbackService.isTimerRunning()) {
            tvTimerRemaining.setText(formatTime(playbackService.getTimerMillisRemaining()));
        } else {
            tvTimerRemaining.setText(R.string.timer_off);
        }
    }

    // ===== Hilfsmethoden =====

    /** Aktualisiert Fortschrittsbalken und Zeitanzeigen. */
    private void updateProgress() {
        if (!isBound || playbackService == null) return;
        int position = playbackService.getCurrentPosition(); // ms
        int duration = playbackService.getDuration();        // ms
        if (duration > 0) {
            int progress = (int) ((long) position * 1000 / duration);
            seekProgress.setProgress(progress);
        } else {
            seekProgress.setProgress(0);
        }
        tvCurrentPosition.setText(formatMs(position));
        tvTrackDurationLabel.setText(formatMs(duration));
    }

    /** Formatiert Millisekunden als M:SS oder H:MM:SS. */
    private String formatMs(long ms) {
        long totalSeconds = ms / 1000;
        long hours = totalSeconds / 3600;
        long minutes = (totalSeconds % 3600) / 60;
        long seconds = totalSeconds % 60;
        if (hours > 0) {
            return String.format(Locale.getDefault(), "%d:%02d:%02d", hours, minutes, seconds);
        }
        return String.format(Locale.getDefault(), "%d:%02d", minutes, seconds);
    }

    private String formatTime(long millis) {
        long totalSeconds = millis / 1000;
        long minutes = totalSeconds / 60;
        long seconds = totalSeconds % 60;
        return String.format(Locale.getDefault(), "%d:%02d", minutes, seconds);
    }

    /**
     * Lädt das Album-Cover mit Glide.
     * Zeigt den Platzhalter wenn kein Cover vorhanden oder das Laden fehlschlägt.
     */
    private void updateAlbumArt(TrackSelector.TrackInfo track) {
        Uri artUri = track != null ? track.getAlbumArtUri() : null;
        Glide.with(this)
                .load(artUri)
                .placeholder(R.drawable.ic_album_placeholder)
                .error(R.drawable.ic_album_placeholder)
                .transition(DrawableTransitionOptions.withCrossFade(300))
                .centerCrop()
                .into(ivAlbumArt);

        // Overlay-Bild ebenfalls aktualisieren falls es gerade sichtbar ist
        if (overlayAlbumArt.getVisibility() == View.VISIBLE) {
            Glide.with(this)
                    .load(artUri)
                    .placeholder(R.drawable.ic_album_placeholder)
                    .error(R.drawable.ic_album_placeholder)
                    .into(ivAlbumArtFull);
        }
    }

    // ===== Album-Art Vollbild-Overlay =====

    private void showAlbumArtOverlay() {
        // Aktuelles Bild in das Vollbild-View laden
        TrackSelector.TrackInfo track = (isBound && playbackService != null)
                ? playbackService.getCurrentTrack() : null;
        Uri artUri = track != null ? track.getAlbumArtUri() : null;

        Glide.with(this)
                .load(artUri)
                .placeholder(R.drawable.ic_album_placeholder)
                .error(R.drawable.ic_album_placeholder)
                .into(ivAlbumArtFull);

        // Einblenden mit Fade-Animation
        AlphaAnimation fadeIn = new AlphaAnimation(0f, 1f);
        fadeIn.setDuration(200);
        overlayAlbumArt.setVisibility(View.VISIBLE);
        overlayAlbumArt.startAnimation(fadeIn);
    }

    private void hideAlbumArtOverlay() {
        AlphaAnimation fadeOut = new AlphaAnimation(1f, 0f);
        fadeOut.setDuration(200);
        fadeOut.setAnimationListener(new Animation.AnimationListener() {
            @Override public void onAnimationStart(Animation a) {}
            @Override public void onAnimationRepeat(Animation a) {}
            @Override public void onAnimationEnd(Animation a) {
                overlayAlbumArt.setVisibility(View.GONE);
            }
        });
        overlayAlbumArt.startAnimation(fadeOut);
    }

    /** Zurück-Taste schließt zuerst das Overlay (falls offen). */
    @Override
    public void onBackPressed() {
        if (overlayAlbumArt != null && overlayAlbumArt.getVisibility() == View.VISIBLE) {
            hideAlbumArtOverlay();
        } else {
            super.onBackPressed();
        }
    }
}

package com.example.sleepplayer;

import android.app.AlertDialog;
import android.Manifest;
import android.content.ComponentName;
import android.content.Intent;
import android.content.ServiceConnection;
import android.content.pm.PackageManager;
import android.database.ContentObserver;
import android.media.AudioManager;
import android.net.Uri;
import android.os.Build;
import android.os.Bundle;
import android.os.Handler;
import android.os.IBinder;
import android.os.Looper;
import android.os.StrictMode;
import android.provider.Settings;
import android.view.View;
import android.view.animation.AlphaAnimation;
import android.view.animation.Animation;
import android.widget.AdapterView;
import android.widget.ArrayAdapter;
import android.widget.ImageButton;
import android.widget.ImageView;
import android.widget.PopupMenu;
import android.widget.SeekBar;
import android.widget.Spinner;
import android.widget.TextView;
import android.widget.ProgressBar;
import android.widget.Toast;

import androidx.activity.result.ActivityResultLauncher;
import androidx.activity.result.contract.ActivityResultContracts;
import androidx.annotation.NonNull;
import androidx.appcompat.app.AppCompatActivity;
import androidx.core.content.ContextCompat;
import androidx.recyclerview.widget.LinearLayoutManager;
import androidx.recyclerview.widget.RecyclerView;

import com.google.android.material.materialswitch.MaterialSwitch;
import com.bumptech.glide.Glide;
import com.bumptech.glide.load.resource.drawable.DrawableTransitionOptions;

import java.util.List;
import java.util.Locale;

/**
 * Haupt-Activity für SleepPlayer.
 *
 * Zeigt:
 * - Aktuellen Track (Titel, Künstler)
 * - Play/Pause und Skip-Buttons
 * - Lautstärke-SeekBar (logarithmisch, feine Schritte im leisen Bereich)
 * - Sleep-Timer mit Auswahl und Restzeit-Anzeige
 * - Liste aller verfügbaren Audio-Tracks
 */
public class MainActivity extends AppCompatActivity implements PlaybackService.PlaybackCallback {

    // Timer-Optionen in Minuten
    private static final int[] TIMER_OPTIONS = {5, 10, 15, 20, 30, 45, 60, 90, 120};

    /** Schrittweite pro Hardware-Lautstärketaste (bezogen auf SEEK_BAR_MAX = 200). */
    private static final int VOLUME_KEY_STEP = 4;

    // System-Audio
    private AudioManager audioManager;
    private ContentObserver volumeObserver;
    private int lastSystemVolume = -1;

    // Views
    private TextView tvTrackName;
    private TextView tvTrackArtist;
    private ImageView ivAlbumArt;
    private ImageButton btnPlayPause;
    private ImageButton btnSkip;
    private ImageButton btnRestartTrack;
    private ImageButton btnSettings;
    private MaterialSwitch switchRandom;
    private SeekBar seekVolume;
    private TextView tvVolumePercent;
    private TextView tvVolumeLabel;
    private Spinner spinnerTimer;
    private TextView tvTimerRemaining;
    private ImageButton btnMeditation;
    private TextView tvTrackCount;
    private RecyclerView recyclerTracks;

    // Vollbild-Overlay für Album Art
    private View overlayAlbumArt;
    private ImageView ivAlbumArtFull;

    // Fortschrittsbalken
    private SeekBar seekProgress;
    private TextView tvCurrentPosition;
    private TextView tvTrackDurationLabel;

    /** Handler + Runnable für die sekündliche Fortschritts-Aktualisierung. */
    private final Handler progressHandler = new Handler(Looper.getMainLooper());
    private final Runnable progressRunnable = new Runnable() {
        @Override
        public void run() {
            updateProgress();
            progressHandler.postDelayed(this, 500);
        }
    };

    // Service
    private PlaybackService playbackService;
    private boolean isBound = false;

    /**
     * Aktion die ausgeführt wird sobald der Service verbunden ist.
     * Wird gesetzt wenn der Nutzer Play/Skip drückt bevor der Service bereit ist.
     */
    private Runnable pendingServiceAction = null;

    // Adapter
    private TrackAdapter trackAdapter;

    // Prefs
    private PrefsManager prefsManager;

    // Normalisierung
    private NormalizationStore normalizationStore;

    // Permission Launcher
    private final ActivityResultLauncher<String> requestPermissionLauncher =
            registerForActivityResult(new ActivityResultContracts.RequestPermission(), granted -> {
                if (granted) {
                    loadTracks();
                } else {
                    Toast.makeText(this, R.string.permission_denied, Toast.LENGTH_LONG).show();
                }
            });

    // Notification Permission Launcher
    private final ActivityResultLauncher<String> requestNotificationLauncher =
            registerForActivityResult(new ActivityResultContracts.RequestPermission(), granted -> {
                // Optional, Notification funktioniert auch ohne auf manchen Geräten
            });

    // Ordner-Picker Launcher (SAF = Storage Access Framework)
    private final ActivityResultLauncher<Uri> folderPickerLauncher =
            registerForActivityResult(new ActivityResultContracts.OpenDocumentTree(), uri -> {
                if (uri != null) {
                    onFolderSelected(uri);
                }
            });

    private final ServiceConnection serviceConnection = new ServiceConnection() {
        @Override
        public void onServiceConnected(ComponentName name, IBinder binder) {
            PlaybackService.LocalBinder localBinder = (PlaybackService.LocalBinder) binder;
            playbackService = localBinder.getService();
            isBound = true;

            playbackService.setCallback(MainActivity.this);

            // UI mit aktuellem Zustand synchronisieren
            syncUI();

            // Ausstehende Aktion ausführen (z.B. Play-Druck während Service noch startete)
            if (pendingServiceAction != null) {
                pendingServiceAction.run();
                pendingServiceAction = null;
            }
        }

        @Override
        public void onServiceDisconnected(ComponentName name) {
            playbackService = null;
            isBound = false;
        }
    };

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);

        // StrictMode im Debug-Build: zeigt Main-Thread I/O sofort im Logcat
        if (BuildConfig.DEBUG) {
            StrictMode.setThreadPolicy(new StrictMode.ThreadPolicy.Builder()
                    .detectDiskReads()
                    .detectDiskWrites()
                    .penaltyLog()
                    .build());
        }

        setContentView(R.layout.activity_main);

        prefsManager = new PrefsManager(this);
        normalizationStore = new NormalizationStore(this);
        audioManager = (AudioManager) getSystemService(AUDIO_SERVICE);

        // Lautstärketasten sollen den Medien-Stream steuern
        setVolumeControlStream(AudioManager.STREAM_MUSIC);

        initViews();
        setupVolumeControl();
        setupTimerSpinner();
        setupRandomSwitch();
        setupSettingsButton();
        setupTrackList();
        checkPermissions();
    }

    @Override
    protected void onStart() {
        super.onStart();
        // An den Service binden (falls er läuft)
        Intent intent = new Intent(this, PlaybackService.class);
        bindService(intent, serviceConnection, 0);
    }

    @Override
    protected void onResume() {
        super.onResume();
        registerVolumeObserver();
        // Fortschrittsbalken starten falls gerade abgespielt wird
        if (isBound && playbackService != null && playbackService.isPlaying()) {
            progressHandler.post(progressRunnable);
        }
    }

    @Override
    protected void onPause() {
        super.onPause();
        unregisterVolumeObserver();
        progressHandler.removeCallbacks(progressRunnable);
    }

    @Override
    protected void onStop() {
        super.onStop();
        pendingServiceAction = null; // ausstehende Aktionen verwerfen
        if (isBound) {
            if (playbackService != null) {
                playbackService.setCallback(null);
            }
            unbindService(serviceConnection);
            isBound = false;
        }
    }

    /**
     * ContentObserver für Systemlautstärke-Änderungen.
     * Funktioniert auch wenn die MediaSession die Tasten abfängt.
     * Erkennt die Richtung der Änderung und verschiebt den in-app Slider
     * um VOLUME_KEY_STEP – so bleibt die logarithmische Feinregelung erhalten.
     */
    private void registerVolumeObserver() {
        lastSystemVolume = audioManager.getStreamVolume(AudioManager.STREAM_MUSIC);
        volumeObserver = new ContentObserver(new Handler(Looper.getMainLooper())) {
            @Override
            public void onChange(boolean selfChange) {
                int newSystemVolume = audioManager.getStreamVolume(AudioManager.STREAM_MUSIC);
                if (newSystemVolume == lastSystemVolume) return;

                boolean volumeUp = newSystemVolume > lastSystemVolume;
                lastSystemVolume = newSystemVolume;

                int current = seekVolume.getProgress();
                int next = volumeUp
                        ? Math.min(VolumeHelper.SEEK_BAR_MAX, current + VOLUME_KEY_STEP)
                        : Math.max(0, current - VOLUME_KEY_STEP);

                if (next != current) {
                    seekVolume.setProgress(next);
                    updateVolumeLabel(next);
                    float volume = VolumeHelper.progressToVolume(next);
                    if (isBound && playbackService != null) {
                        playbackService.setVolume(volume);
                    }
                    prefsManager.saveVolume(next);
                }
            }
        };
        getContentResolver().registerContentObserver(
                Settings.System.CONTENT_URI, true, volumeObserver);
    }

    private void unregisterVolumeObserver() {
        if (volumeObserver != null) {
            getContentResolver().unregisterContentObserver(volumeObserver);
            volumeObserver = null;
        }
    }

    // ===== Initialisierung =====

    private void initViews() {
        tvTrackName = findViewById(R.id.tvTrackName);
        tvTrackArtist = findViewById(R.id.tvTrackArtist);
        ivAlbumArt = findViewById(R.id.ivAlbumArt);
        btnPlayPause = findViewById(R.id.btnPlayPause);
        btnSkip = findViewById(R.id.btnSkip);
        btnRestartTrack = findViewById(R.id.btnRestartTrack);
        btnSettings = findViewById(R.id.btnSettings);
        switchRandom = findViewById(R.id.switchRandom);
        seekVolume = findViewById(R.id.seekVolume);
        tvVolumePercent = findViewById(R.id.tvVolumePercent);
        tvVolumeLabel = findViewById(R.id.tvVolumeLabel);
        spinnerTimer = findViewById(R.id.spinnerTimer);
        tvTimerRemaining = findViewById(R.id.tvTimerRemaining);
        btnMeditation = findViewById(R.id.btnMeditation);
        tvTrackCount = findViewById(R.id.tvTrackCount);
        recyclerTracks = findViewById(R.id.recyclerTracks);
        overlayAlbumArt = findViewById(R.id.overlayAlbumArt);
        ivAlbumArtFull = findViewById(R.id.ivAlbumArtFull);
        seekProgress = findViewById(R.id.seekProgress);
        tvCurrentPosition = findViewById(R.id.tvCurrentPosition);
        tvTrackDurationLabel = findViewById(R.id.tvTrackDurationLabel);

        btnPlayPause.setOnClickListener(v -> onPlayPauseClicked());
        btnSkip.setOnClickListener(v -> onSkipClicked());
        btnRestartTrack.setOnClickListener(v -> onRestartTrackClicked());

        // Meditations-Button: togglet die 4-7-8 Atemübung (wie Doppelklick am Kopfhörer)
        btnMeditation.setOnClickListener(v -> {
            ensureServiceStarted();
            if (isBound && playbackService != null) {
                playbackService.toggleMeditation();
            } else {
                pendingServiceAction = () -> playbackService.toggleMeditation();
            }
        });

        // Klick auf kleines Album-Art → Vollbild-Overlay öffnen
        ivAlbumArt.setOnClickListener(v -> showAlbumArtOverlay());

        // Klick irgendwo im Overlay → schließen
        overlayAlbumArt.setOnClickListener(v -> hideAlbumArtOverlay());

        // Fortschrittsbalken: Nutzer kann Position manuell setzen
        seekProgress.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener() {
            @Override public void onProgressChanged(SeekBar s, int p, boolean fromUser) {}
            @Override public void onStartTrackingTouch(SeekBar s) {
                // Aktualisierung pausieren während der Nutzer zieht
                progressHandler.removeCallbacks(progressRunnable);
            }
            @Override public void onStopTrackingTouch(SeekBar s) {
                if (isBound && playbackService != null) {
                    int duration = playbackService.getDuration();
                    if (duration > 0) {
                        int seekMs = (int) ((long) s.getProgress() * duration / 1000);
                        playbackService.seekTo(seekMs);
                    }
                }
                // Aktualisierung wieder starten
                progressHandler.post(progressRunnable);
            }
        });
    }

    private void setupVolumeControl() {
        seekVolume.setMax(VolumeHelper.SEEK_BAR_MAX);

        // Gespeicherten Wert laden
        int savedProgress = prefsManager.getVolume();
        seekVolume.setProgress(savedProgress);
        updateVolumeLabel(savedProgress);

        seekVolume.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener() {
            @Override
            public void onProgressChanged(SeekBar seekBar, int progress, boolean fromUser) {
                if (fromUser) {
                    float volume = VolumeHelper.progressToVolume(progress);
                    if (isBound && playbackService != null) {
                        playbackService.setVolume(volume);
                    }
                    updateVolumeLabel(progress);
                    prefsManager.saveVolume(progress);
                }
            }

            @Override
            public void onStartTrackingTouch(SeekBar seekBar) {}

            @Override
            public void onStopTrackingTouch(SeekBar seekBar) {}
        });
    }

    private void updateVolumeLabel(int progress) {
        int percent = VolumeHelper.progressToPercent(progress);
        tvVolumePercent.setText(String.format(Locale.getDefault(), "%d%%", percent));
        tvVolumeLabel.setText(String.format(Locale.getDefault(),
                getString(R.string.volume_label), percent));
    }

    private void setupTimerSpinner() {
        String[] timerLabels = new String[TIMER_OPTIONS.length];
        for (int i = 0; i < TIMER_OPTIONS.length; i++) {
            timerLabels[i] = TIMER_OPTIONS[i] + " " + getString(R.string.minutes_suffix);
        }

        ArrayAdapter<String> adapter = new ArrayAdapter<>(this,
                android.R.layout.simple_spinner_item, timerLabels);
        adapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);
        spinnerTimer.setAdapter(adapter);

        // Gespeicherten Wert auswählen
        int savedMinutes = prefsManager.getTimerMinutes();
        for (int i = 0; i < TIMER_OPTIONS.length; i++) {
            if (TIMER_OPTIONS[i] == savedMinutes) {
                spinnerTimer.setSelection(i);
                break;
            }
        }

        spinnerTimer.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener() {
            @Override
            public void onItemSelected(AdapterView<?> parent, View view, int pos, long id) {
                int minutes = TIMER_OPTIONS[pos];
                prefsManager.saveTimerMinutes(minutes);
                if (isBound && playbackService != null && playbackService.isTimerRunning()) {
                    // Timer mit neuer Dauer neu starten
                    playbackService.startTimer(minutes);
                }
            }

            @Override
            public void onNothingSelected(AdapterView<?> parent) {}
        });
    }

    private void setupTrackList() {
        trackAdapter = new TrackAdapter();
        trackAdapter.setNormalizationStore(normalizationStore);
        recyclerTracks.setLayoutManager(new LinearLayoutManager(this));
        recyclerTracks.setAdapter(trackAdapter);

        trackAdapter.setOnTrackClickListener(track -> {
            ensureServiceStarted();
            if (isBound && playbackService != null) {
                playbackService.playTrack(track);
            } else {
                pendingServiceAction = () -> playbackService.playTrack(track);
            }
        });

        // Longpress → Referenz-Track setzen
        trackAdapter.setOnTrackLongClickListener(track -> showReferenceTrackMenu(track));
    }

    private void setupRandomSwitch() {
        // Gespeicherten Modus laden
        boolean savedRandom = prefsManager.isRandomMode();
        switchRandom.setChecked(savedRandom);
        switchRandom.setText(savedRandom ? R.string.mode_random : R.string.mode_sequential);

        switchRandom.setOnCheckedChangeListener((button, isChecked) -> {
            prefsManager.saveRandomMode(isChecked);
            button.setText(isChecked ? R.string.mode_random : R.string.mode_sequential);
            if (isBound && playbackService != null) {
                playbackService.setRandomMode(isChecked);
            }
        });
    }

    // ===== Settings-Button / Ordner-Auswahl =====

    private void setupSettingsButton() {
        btnSettings.setOnClickListener(v -> showSettingsMenu());
    }

    /**
     * Zeigt ein PopupMenu mit Ordner-Auswahl-Optionen, TTS-Toggle und Normalisierung.
     */
    private void showSettingsMenu() {
        PopupMenu popup = new PopupMenu(this, btnSettings);

        // Aktuellen Ordner als erstes (deaktiviertes) Item anzeigen
        String folderName = prefsManager.getFolderDisplayName();
        String folderLabel = (folderName != null)
                ? getString(R.string.settings_folder_title) + ": " + folderName
                : getString(R.string.settings_folder_title) + ": " + getString(R.string.folder_all);
        popup.getMenu().add(0, 0, 0, folderLabel).setEnabled(false);
        popup.getMenu().add(0, 1, 1, getString(R.string.settings_folder_select));
        popup.getMenu().add(0, 2, 2, getString(R.string.settings_folder_clear))
                .setEnabled(folderName != null);

        // TTS-Toggle
        boolean ttsEnabled = prefsManager.isTtsEnabled();
        popup.getMenu().add(0, 3, 3,
                ttsEnabled ? getString(R.string.tts_on) : getString(R.string.tts_off));

        // Normalisierung – "Normalisieren" immer aktiv (zeigt eigene Hinweise wenn nötig),
        // "Zurücksetzen" nur aktiv wenn überhaupt Gain-Daten vorhanden
        popup.getMenu().add(0, 4, 4, getString(R.string.norm_menu_normalize))
                .setEnabled(true);
        popup.getMenu().add(0, 5, 5, getString(R.string.norm_menu_reset))
                .setEnabled(!normalizationStore.getAllGains().isEmpty());

        // Referenz-Info (deaktiviert, nur zur Info)
        String refTitle = normalizationStore.getReferenceTrackTitle();
        if (refTitle != null) {
            popup.getMenu().add(0, 6, 6, "⭐ " + getString(R.string.norm_ref_label) + ": " + refTitle)
                    .setEnabled(false);
        } else {
            popup.getMenu().add(0, 6, 6, getString(R.string.norm_ref_hint))
                    .setEnabled(false);
        }

        popup.setOnMenuItemClickListener(item -> {
            switch (item.getItemId()) {
                case 1:
                    folderPickerLauncher.launch(null);
                    return true;
                case 2:
                    prefsManager.clearFolder();
                    loadTracks();
                    Toast.makeText(this, R.string.folder_all, Toast.LENGTH_SHORT).show();
                    return true;
                case 3:
                    boolean newTts = !prefsManager.isTtsEnabled();
                    prefsManager.saveTtsEnabled(newTts);
                    Toast.makeText(this,
                            newTts ? R.string.tts_on : R.string.tts_off,
                            Toast.LENGTH_SHORT).show();
                    return true;
                case 4:
                    startNormalization();
                    return true;
                case 5:
                    normalizationStore.clearGains();   // Nur Gains löschen, Referenz-Track bleibt erhalten
                    trackAdapter.notifyDataSetChanged();
                    Toast.makeText(this, R.string.norm_reset_done, Toast.LENGTH_SHORT).show();
                    return true;
            }
            return false;
        });
        popup.show();
    }

    /**
     * Zeigt ein Kontextmenü zum Setzen des Referenz-Tracks und Normalisierungsoptionen (nach Longpress).
     */
    private void showReferenceTrackMenu(TrackSelector.TrackInfo track) {
        boolean hasSectional = normalizationStore.hasSectionalGains(track.uri.toString());
        java.util.List<String> items = new java.util.ArrayList<>();
        items.add(getString(R.string.norm_set_ref_confirm));
        items.add(getString(R.string.norm_single_track));
        items.add(getString(R.string.norm_sectional));
        if (hasSectional) {
            items.add(getString(R.string.norm_sectional_visualize));
            items.add(getString(R.string.norm_sectional_clear));
        }

        new AlertDialog.Builder(this)
                .setTitle(track.title)
                .setItems(items.toArray(new String[0]), (d, which) -> {
                    String chosen = items.get(which);
                    if (chosen.equals(getString(R.string.norm_set_ref_confirm))) {
                        normalizationStore.saveReferenceTrack(track.uri.toString(), track.title);
                        trackAdapter.notifyDataSetChanged();
                        Toast.makeText(this, getString(R.string.norm_ref_set, track.title), Toast.LENGTH_SHORT).show();
                    } else if (chosen.equals(getString(R.string.norm_single_track))) {
                        startSingleTrackNormalization(track);
                    } else if (chosen.equals(getString(R.string.norm_sectional))) {
                        startSectionalNormalization(track);
                    } else if (chosen.equals(getString(R.string.norm_sectional_visualize))) {
                        showSectionalGainChart(track);
                    } else if (chosen.equals(getString(R.string.norm_sectional_clear))) {
                        normalizationStore.clearSectionalGains(track.uri.toString());
                        trackAdapter.notifyDataSetChanged();
                        Toast.makeText(this, getString(R.string.norm_reset_done), Toast.LENGTH_SHORT).show();
                    }
                })
                .setNegativeButton(android.R.string.cancel, null)
                .show();
    }

    /**
     * Zeigt ein Diagramm der sektionsweisen Gain-Anpassungen für einen Track.
     * Grüne Balken = leise Stellen werden angehoben, orange = laute werden gedämpft.
     * Eine pinke Linie zeigt die aktuelle Wiedergabeposition (falls dieser Track spielt).
     */
    private void showSectionalGainChart(TrackSelector.TrackInfo track) {
        java.util.List<float[]> sections = normalizationStore.getSectionalGains(track.uri.toString());
        if (sections == null || sections.isEmpty()) {
            Toast.makeText(this, R.string.norm_no_tracks, Toast.LENGTH_SHORT).show();
            return;
        }

        SectionalGainChartView chartView = new SectionalGainChartView(this);
        chartView.setSections(sections);

        // Aktuelle Wiedergabeposition eintragen, falls dieser Track gerade spielt
        if (isBound && playbackService != null && playbackService.getCurrentTrack() != null
                && playbackService.getCurrentTrack().uri.toString().equals(track.uri.toString())) {
            chartView.setCurrentPosition(playbackService.getCurrentPosition());
        }

        // Höhe: 260dp
        int heightPx = (int)(260 * getResources().getDisplayMetrics().density);
        chartView.setMinimumHeight(heightPx);

        // Zusammenfassung unter dem Diagramm
        int boostCount = 0, cutCount = 0, neutralCount = 0;
        float maxBoostDb = 0f, maxCutDb = 0f;
        for (float[] s : sections) {
            float db = (float)(20.0 * Math.log10(Math.max(1e-6, s[1])));
            if (db > 0.5f) { boostCount++; maxBoostDb = Math.max(maxBoostDb, db); }
            else if (db < -0.5f) { cutCount++; maxCutDb = Math.max(maxCutDb, -db); }
            else neutralCount++;
        }
        String summary = String.format(Locale.getDefault(),
                "%d Sektionen  •  ▲ %d angehoben (max +%.1fdB)  •  ▼ %d gedämpft (max −%.1fdB)  •  %d neutral",
                sections.size(), boostCount, maxBoostDb, cutCount, maxCutDb, neutralCount);

        android.widget.LinearLayout layout = new android.widget.LinearLayout(this);
        layout.setOrientation(android.widget.LinearLayout.VERTICAL);
        layout.addView(chartView);

        TextView summaryView = new TextView(this);
        summaryView.setText(summary);
        summaryView.setTextColor(0xFF90A4AE);
        summaryView.setTextSize(11f);
        int pad = (int)(12 * getResources().getDisplayMetrics().density);
        summaryView.setPadding(pad, pad/2, pad, pad);
        layout.addView(summaryView);

        new AlertDialog.Builder(this)
                .setTitle(getString(R.string.norm_sectional_chart_title) + "\n" + track.title)
                .setView(layout)
                .setPositiveButton(android.R.string.ok, null)
                // "Neu analysieren" Shortcut
                .setNeutralButton(getString(R.string.norm_sectional), (d, w) -> startSectionalNormalization(track))
                .show();
    }

    /**
     * Normalisiert einen einzelnen Track gegen den Referenz-Track.
     */
    private void startSingleTrackNormalization(TrackSelector.TrackInfo track) {
        String refUri = normalizationStore.getReferenceTrackUri();
        if (refUri == null) {
            new AlertDialog.Builder(this)
                    .setTitle(getString(R.string.norm_menu_normalize))
                    .setMessage(getString(R.string.norm_no_ref))
                    .setPositiveButton(android.R.string.ok, null).show();
            return;
        }

        // Fortschritts-Dialog
        android.widget.ProgressBar pb = new android.widget.ProgressBar(this, null,
                android.R.attr.progressBarStyleHorizontal);
        pb.setMax(100);
        int pad = (int)(16 * getResources().getDisplayMetrics().density);
        pb.setPadding(pad, pad, pad, pad);
        AlertDialog dlg = new AlertDialog.Builder(this)
                .setTitle(R.string.norm_progress_title)
                .setMessage(track.title)
                .setView(pb)
                .setCancelable(false)
                .create();
        dlg.show();

        new Thread(() -> {
            // Referenz-RMS
            float refDb = Float.NaN;
            if (track.uri.toString().equals(refUri)) {
                refDb = AudioAnalyzer.analyzeRmsDb(this, track.uri, p -> runOnUiThread(() -> pb.setProgress(p)));
            } else {
                // Analyse der Referenz (schnell, nur 60s)
                TrackSelector selector = isBound && playbackService != null
                        ? playbackService.getTrackSelector() : new TrackSelector(this);
                for (TrackSelector.TrackInfo t : selector.getAllTracks()) {
                    if (t.uri.toString().equals(refUri)) {
                        refDb = AudioAnalyzer.analyzeRmsDb(this, t.uri);
                        break;
                    }
                }
                if (Float.isNaN(refDb)) {
                    runOnUiThread(() -> { dlg.dismiss();
                        Toast.makeText(this, R.string.norm_ref_analysis_failed, Toast.LENGTH_LONG).show(); });
                    return;
                }
                float trackDb = AudioAnalyzer.analyzeRmsDb(this, track.uri,
                        p -> runOnUiThread(() -> pb.setProgress(p)));
                if (Float.isNaN(trackDb)) {
                    runOnUiThread(() -> { dlg.dismiss();
                        Toast.makeText(this, R.string.norm_track_analysis_failed, Toast.LENGTH_LONG).show(); });
                    return;
                }
                float gain = NormalizationStore.computeGainMultiplier(refDb, trackDb);
                normalizationStore.saveGain(track.uri.toString(), gain);
                String gainStr = String.format(java.util.Locale.getDefault(), "%.2f", gain);
                runOnUiThread(() -> { dlg.dismiss(); trackAdapter.notifyDataSetChanged();
                    Toast.makeText(this, getString(R.string.norm_single_done, gainStr), Toast.LENGTH_LONG).show(); });
                return;
            }
            // Track ist selbst der Referenz-Track → Gain 1.0
            normalizationStore.saveGain(track.uri.toString(), 1.0f);
            runOnUiThread(() -> { dlg.dismiss(); trackAdapter.notifyDataSetChanged();
                Toast.makeText(this, getString(R.string.norm_single_done, "1.00"), Toast.LENGTH_SHORT).show(); });
        }, "SingleNormThread").start();
    }

    /**
     * Sektionsweise Normalisierung für einen einzelnen Track.
     * Fragt zuerst nach der gewünschten Sektionslänge (1–30 Sek.), dann Analyse.
     */
    private void startSectionalNormalization(TrackSelector.TrackInfo track) {
        String refUri = normalizationStore.getReferenceTrackUri();
        if (refUri == null) {
            new AlertDialog.Builder(this)
                    .setTitle(getString(R.string.norm_menu_normalize))
                    .setMessage(getString(R.string.norm_no_ref))
                    .setPositiveButton(android.R.string.ok, null).show();
            return;
        }

        // Sektionslänge-Dialog mit SeekBar (1–30 Sek.)
        int currentSec = prefsManager.getSectionLengthSec();

        android.widget.LinearLayout layout = new android.widget.LinearLayout(this);
        layout.setOrientation(android.widget.LinearLayout.VERTICAL);
        int pad = (int)(16 * getResources().getDisplayMetrics().density);
        layout.setPadding(pad, pad, pad, 0);

        TextView labelView = new TextView(this);
        labelView.setTextColor(0xFFFFFFFF);
        labelView.setTextSize(14f);
        labelView.setText(getString(R.string.norm_section_length_label, currentSec));

        SeekBar seekBar = new SeekBar(this);
        seekBar.setMax(29);                        // 0–29 → Sekunden 1–30
        seekBar.setProgress(currentSec - 1);
        seekBar.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener() {
            @Override public void onProgressChanged(SeekBar s, int p, boolean fromUser) {
                labelView.setText(getString(R.string.norm_section_length_label, p + 1));
            }
            @Override public void onStartTrackingTouch(SeekBar s) {}
            @Override public void onStopTrackingTouch(SeekBar s) {}
        });

        layout.addView(labelView);
        layout.addView(seekBar);

        new AlertDialog.Builder(this)
                .setTitle(getString(R.string.norm_sectional))
                .setMessage(track.title)
                .setView(layout)
                .setPositiveButton(getString(R.string.norm_start_analysis), (d, w) -> {
                    int chosenSec = seekBar.getProgress() + 1;
                    prefsManager.saveSectionLengthSec(chosenSec);
                    runSectionalNormalization(track, chosenSec * 1000);
                })
                .setNegativeButton(android.R.string.cancel, null)
                .show();
    }

    /** Führt die eigentliche sektionsweise Analyse durch (nach Bestätigung der Sektionslänge). */
    private void runSectionalNormalization(TrackSelector.TrackInfo track, int sectionLengthMs) {
        String refUri = normalizationStore.getReferenceTrackUri();
        if (refUri == null) {
            new AlertDialog.Builder(this)
                    .setTitle(getString(R.string.norm_menu_normalize))
                    .setMessage(getString(R.string.norm_no_ref))
                    .setPositiveButton(android.R.string.ok, null).show();
            return;
        }

        android.widget.ProgressBar pb = new android.widget.ProgressBar(this, null,
                android.R.attr.progressBarStyleHorizontal);
        pb.setMax(100);
        int pad = (int)(16 * getResources().getDisplayMetrics().density);
        pb.setPadding(pad, pad, pad, pad);
        AlertDialog dlg = new AlertDialog.Builder(this)
                .setTitle(R.string.norm_sectional_title)
                .setMessage(track.title)
                .setView(pb)
                .setCancelable(false)
                .create();
        dlg.show();

        new Thread(() -> {
            // Referenz-RMS (Gesamtlevel als Ziel)
            float refDb = Float.NaN;
            TrackSelector selector = isBound && playbackService != null
                    ? playbackService.getTrackSelector() : new TrackSelector(this);
            for (TrackSelector.TrackInfo t : selector.getAllTracks()) {
                if (t.uri.toString().equals(refUri)) {
                    refDb = AudioAnalyzer.analyzeRmsDb(this, t.uri);
                    break;
                }
            }
            if (Float.isNaN(refDb)) {
                final float finalRefDb = refDb;
                runOnUiThread(() -> { dlg.dismiss();
                    Toast.makeText(this, R.string.norm_ref_analysis_failed, Toast.LENGTH_LONG).show(); });
                return;
            }

            final float targetDb = refDb;
            // Sektionsweise Analyse des Tracks
            java.util.List<float[]> sections = AudioAnalyzer.analyzeSectionsDb(
                    this, track.uri, sectionLengthMs,
                    p -> runOnUiThread(() -> pb.setProgress(p)));

            if (sections.isEmpty()) {
                runOnUiThread(() -> { dlg.dismiss();
                    Toast.makeText(this, R.string.norm_track_analysis_failed, Toast.LENGTH_LONG).show(); });
                return;
            }

            // Für jede Sektion Gain berechnen: [startMs, gainMul]
            java.util.List<float[]> sectionalGains = new java.util.ArrayList<>();
            for (float[] s : sections) {
                float sectionDb = s[1];
                float gain = Float.isNaN(sectionDb) || sectionDb <= -99f
                        ? 1.0f
                        : NormalizationStore.computeGainMultiplier(targetDb, sectionDb);
                // Auf ±18 dB begrenzen
                float maxMul = (float) Math.pow(10, NormalizationStore.MAX_GAIN_DB / 20f);
                gain = Math.max(1f / maxMul, Math.min(maxMul, gain));
                sectionalGains.add(new float[]{s[0], gain});
            }

            normalizationStore.saveSectionalGains(track.uri.toString(), sectionalGains);
            final int count = sectionalGains.size();
            runOnUiThread(() -> { dlg.dismiss(); trackAdapter.notifyDataSetChanged();
                Toast.makeText(this, getString(R.string.norm_sectional_done, count), Toast.LENGTH_LONG).show(); });
        }, "SectionalNormThread").start();
    }

    /**
     * Startet die Normalisierungs-Analyse für alle Tracks im Hintergrund.
     * Zeigt einen Fortschritts-Dialog und speichert die Gains danach.
     */
    private void startNormalization() {
        // Track-Liste holen (bereits geladen im Adapter)
        List<TrackSelector.TrackInfo> allTracks;
        try {
            // Tracks via TrackSelector neu laden (sicher, eigener Thread folgt)
            TrackSelector selector = isBound && playbackService != null
                    ? playbackService.getTrackSelector()
                    : new TrackSelector(this);
            allTracks = selector.getAllTracks();
        } catch (Exception e) {
            Toast.makeText(this, R.string.norm_no_tracks, Toast.LENGTH_SHORT).show();
            return;
        }
        if (allTracks.isEmpty()) {
            Toast.makeText(this, R.string.norm_no_tracks, Toast.LENGTH_SHORT).show();
            return;
        }

        String refUri = normalizationStore.getReferenceTrackUri();
        if (refUri == null) {
            // Kein Referenz-Track → erklärenden Dialog zeigen
            new AlertDialog.Builder(this)
                    .setTitle(getString(R.string.norm_menu_normalize))
                    .setMessage(getString(R.string.norm_no_ref))
                    .setPositiveButton(android.R.string.ok, null)
                    .show();
            return;
        }

        // Fortschritts-Dialog aufbauen
        ProgressBar progressBar = new ProgressBar(this, null, android.R.attr.progressBarStyleHorizontal);
        progressBar.setMax(allTracks.size());
        progressBar.setProgress(0);
        int padding = (int) (16 * getResources().getDisplayMetrics().density);
        progressBar.setPadding(padding, padding, padding, padding);

        AlertDialog progressDialog = new AlertDialog.Builder(this)
                .setTitle(R.string.norm_progress_title)
                .setMessage(getString(R.string.norm_progress_msg, 0, allTracks.size()))
                .setView(progressBar)
                .setCancelable(false)
                .create();
        progressDialog.show();

        // Analyse im Hintergrund
        new Thread(() -> {
            // 1) Referenz-RMS berechnen
            TrackSelector.TrackInfo refTrack = null;
            for (TrackSelector.TrackInfo t : allTracks) {
                if (t.uri.toString().equals(refUri)) {
                    refTrack = t;
                    break;
                }
            }
            if (refTrack == null) {
                runOnUiThread(() -> {
                    progressDialog.dismiss();
                    Toast.makeText(this, R.string.norm_ref_not_found, Toast.LENGTH_LONG).show();
                });
                return;
            }

            float refDb = AudioAnalyzer.analyzeRmsDb(this, refTrack.uri);
            if (Float.isNaN(refDb)) {
                runOnUiThread(() -> {
                    progressDialog.dismiss();
                    Toast.makeText(this, R.string.norm_ref_analysis_failed, Toast.LENGTH_LONG).show();
                });
                return;
            }

            // 2) Alle anderen Tracks analysieren
            int analyzed = 0;
            int failed = 0;
            final int total = allTracks.size();

            for (TrackSelector.TrackInfo track : allTracks) {
                analyzed++;
                final int progress = analyzed;

                runOnUiThread(() -> {
                    progressBar.setProgress(progress);
                    progressDialog.setMessage(
                            getString(R.string.norm_progress_msg, progress, total));
                });

                String trackUri = track.uri.toString();
                if (trackUri.equals(refUri)) {
                    // Referenz selbst bekommt Gain 1.0
                    normalizationStore.saveGain(trackUri, 1.0f);
                    continue;
                }

                float trackDb = AudioAnalyzer.analyzeRmsDb(this, track.uri);
                if (Float.isNaN(trackDb)) {
                    failed++;
                    android.util.Log.w("MainActivity", "Analyse fehlgeschlagen: " + track.title);
                    continue;
                }

                float gain = NormalizationStore.computeGainMultiplier(refDb, trackDb);
                normalizationStore.saveGain(trackUri, gain);
            }

            final int finalFailed = failed;
            runOnUiThread(() -> {
                progressDialog.dismiss();
                trackAdapter.notifyDataSetChanged();
                String msg = getString(R.string.norm_done, total - finalFailed, total);
                if (finalFailed > 0) {
                    msg += " (" + getString(R.string.norm_failed_count, finalFailed) + ")";
                }
                Toast.makeText(this, msg, Toast.LENGTH_LONG).show();
            });

        }, "NormalizationThread").start();
    }

    /**
     * Wird aufgerufen wenn der Benutzer einen Ordner ausgewählt hat.
     */
    private void onFolderSelected(Uri treeUri) {
        String displayName = extractFolderDisplayName(treeUri);
        prefsManager.saveFolderUri(treeUri.toString());
        prefsManager.saveFolderDisplayName(displayName);
        loadTracks();
        Toast.makeText(this, getString(R.string.settings_folder_title) + ": " + displayName,
                Toast.LENGTH_SHORT).show();
    }

    /**
     * Extrahiert einen lesbaren Ordnernamen aus einem SAF Tree-URI.
     * z.B. "content://...externalstorage.../tree/primary%3AMusic%2FSleep"
     *  → "Music/Sleep"
     */
    private String extractFolderDisplayName(Uri treeUri) {
        String path = treeUri.getPath();
        if (path != null && path.startsWith("/tree/")) {
            String docId = path.substring(6); // nach "/tree/"
            // docId: "primary:Music/Sleep" oder "XXXX-XXXX:Folder"
            int colonIndex = docId.indexOf(':');
            if (colonIndex >= 0 && colonIndex < docId.length() - 1) {
                return docId.substring(colonIndex + 1);
            }
        }
        // Fallback: letztes Segment des URI
        return treeUri.getLastPathSegment();
    }

    // ===== Permissions =====

    private void checkPermissions() {
        // Audio Permission
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
            if (ContextCompat.checkSelfPermission(this, Manifest.permission.READ_MEDIA_AUDIO)
                    != PackageManager.PERMISSION_GRANTED) {
                requestPermissionLauncher.launch(Manifest.permission.READ_MEDIA_AUDIO);
            } else {
                loadTracks();
            }
        } else {
            if (ContextCompat.checkSelfPermission(this, Manifest.permission.READ_EXTERNAL_STORAGE)
                    != PackageManager.PERMISSION_GRANTED) {
                requestPermissionLauncher.launch(Manifest.permission.READ_EXTERNAL_STORAGE);
            } else {
                loadTracks();
            }
        }

        // Notification Permission (API 33+)
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
            if (ContextCompat.checkSelfPermission(this, Manifest.permission.POST_NOTIFICATIONS)
                    != PackageManager.PERMISSION_GRANTED) {
                requestNotificationLauncher.launch(Manifest.permission.POST_NOTIFICATIONS);
            }
        }
    }

    private void loadTracks() {
        // MediaStore-Query im Hintergrund laden (kein Main-Thread I/O)
        new Thread(() -> {
            TrackSelector selector = new TrackSelector(this);
            selector.clearCache();
            List<TrackSelector.TrackInfo> tracks = selector.getAllTracks();
            runOnUiThread(() -> {
                trackAdapter.setTracks(tracks);
                tvTrackCount.setText(String.format(Locale.getDefault(),
                        getString(R.string.tracks_found), tracks.size()));
                if (tracks.isEmpty()) {
                    tvTrackName.setText(R.string.no_audio_files);
                } else {
                    // Zufälligen Track vorauswählen und im UI anzeigen,
                    // falls gerade nichts spielt – so sieht der Nutzer sofort
                    // welcher Track beim ersten Play-Druck gestartet wird.
                    boolean nothingPlaying = !isBound
                            || playbackService == null
                            || playbackService.getCurrentTrack() == null;
                    if (nothingPlaying) {
                        int idx = (int) (Math.random() * tracks.size());
                        TrackSelector.TrackInfo preselected = tracks.get(idx);
                        tvTrackName.setText(preselected.title);
                        tvTrackArtist.setText(preselected.artist);
                        updateAlbumArt(preselected);
                    }
                }
            });
        }, "LoadTracks").start();
    }

    // ===== Playback Controls =====

    private void onPlayPauseClicked() {
        ensureServiceStarted();
        if (isBound && playbackService != null) {
            playbackService.togglePlayPause();
        } else {
            // Service startet gerade async – Aktion merken und in onServiceConnected ausführen
            pendingServiceAction = () -> playbackService.togglePlayPause();
        }
    }

    private void onSkipClicked() {
        ensureServiceStarted();
        if (isBound && playbackService != null) {
            playbackService.skipToNext();
        } else {
            pendingServiceAction = () -> playbackService.skipToNext();
        }
    }

    /** Setzt den aktuellen Titel auf Position 0 zurück (Anfang des Tracks). */
    private void onRestartTrackClicked() {
        ensureServiceStarted();
        if (isBound && playbackService != null) {
            playbackService.seekTo(0);
        } else {
            pendingServiceAction = () -> playbackService.seekTo(0);
        }
    }

    /**
     * Stellt sicher, dass der Service gestartet und gebunden ist.
     */
    private void ensureServiceStarted() {
        Intent intent = new Intent(this, PlaybackService.class);
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            startForegroundService(intent);
        } else {
            startService(intent);
        }

        if (!isBound) {
            bindService(intent, serviceConnection, BIND_AUTO_CREATE);
        }
    }

    // ===== PlaybackCallback Implementierung =====

    @Override
    public void onTrackChanged(TrackSelector.TrackInfo track) {
        runOnUiThread(() -> {
            if (track != null) {
                tvTrackName.setText(track.title);
                tvTrackArtist.setText(track.artist);
                updateAlbumArt(track);
            }
            // Fortschritt zurücksetzen bis die neue Position eintrifft
            seekProgress.setProgress(0);
            tvCurrentPosition.setText("0:00");
            tvTrackDurationLabel.setText(formatMs(track != null ? track.duration : 0));
        });
    }

    @Override
    public void onPlaybackStateChanged(boolean isPlaying) {
        runOnUiThread(() -> {
            btnPlayPause.setImageResource(isPlaying ? R.drawable.ic_pause : R.drawable.ic_play);
            btnPlayPause.setContentDescription(getString(isPlaying ? R.string.pause : R.string.play));
            if (isPlaying) {
                progressHandler.post(progressRunnable);
            } else {
                progressHandler.removeCallbacks(progressRunnable);
            }
        });
    }

    @Override
    public void onTimerTick(long millisRemaining) {
        runOnUiThread(() -> {
            tvTimerRemaining.setText(formatTime(millisRemaining));
        });
    }

    @Override
    public void onTimerFinished() {
        runOnUiThread(() -> {
            tvTimerRemaining.setText(R.string.timer_off);
            btnPlayPause.setImageResource(R.drawable.ic_play);
            btnPlayPause.setContentDescription(getString(R.string.play));
        });
    }

    @Override
    public void onMeditationStateChanged(boolean active,
            MeditationController.Phase phase, int cycle) {
        runOnUiThread(() -> {
            if (active) {
                // Meditation aktiv: voll sichtbar + türkis eingefärbt
                btnMeditation.setAlpha(1.0f);
                btnMeditation.setColorFilter(
                        ContextCompat.getColor(this, R.color.teal_200),
                        android.graphics.PorterDuff.Mode.SRC_IN);
            } else {
                // Meditation inaktiv: gedimmt + keine Färbung
                btnMeditation.setAlpha(0.6f);
                btnMeditation.clearColorFilter();
            }
            btnMeditation.setContentDescription(
                    getString(active ? R.string.meditation_stop : R.string.meditation_start));
        });
    }

    // ===== UI Sync =====

    private void syncUI() {
        if (!isBound || playbackService == null) return;

        // Aktuellen Track anzeigen
        TrackSelector.TrackInfo track = playbackService.getCurrentTrack();
        if (track != null) {
            tvTrackName.setText(track.title);
            tvTrackArtist.setText(track.artist);
            updateAlbumArt(track);
        }

        // Play/Pause Button
        boolean playing = playbackService.isPlaying();
        btnPlayPause.setImageResource(playing ? R.drawable.ic_pause : R.drawable.ic_play);

        // Random Switch mit Service-Zustand synchronisieren
        boolean random = playbackService.isRandomMode();
        switchRandom.setOnCheckedChangeListener(null); // Listener kurz deaktivieren
        switchRandom.setChecked(random);
        switchRandom.setText(random ? R.string.mode_random : R.string.mode_sequential);
        switchRandom.setOnCheckedChangeListener((button, isChecked) -> {
            prefsManager.saveRandomMode(isChecked);
            button.setText(isChecked ? R.string.mode_random : R.string.mode_sequential);
            if (isBound && playbackService != null) {
                playbackService.setRandomMode(isChecked);
            }
        });

        // Timer
        if (playbackService.isTimerRunning()) {
            tvTimerRemaining.setText(formatTime(playbackService.getTimerMillisRemaining()));
        } else {
            tvTimerRemaining.setText(R.string.timer_off);
        }
    }

    // ===== Hilfsmethoden =====

    /** Aktualisiert Fortschrittsbalken und Zeitanzeigen. */
    private void updateProgress() {
        if (!isBound || playbackService == null) return;
        int position = playbackService.getCurrentPosition(); // ms
        int duration = playbackService.getDuration();        // ms
        if (duration > 0) {
            int progress = (int) ((long) position * 1000 / duration);
            seekProgress.setProgress(progress);
        } else {
            seekProgress.setProgress(0);
        }
        tvCurrentPosition.setText(formatMs(position));
        tvTrackDurationLabel.setText(formatMs(duration));
    }

    /** Formatiert Millisekunden als M:SS oder H:MM:SS. */
    private String formatMs(long ms) {
        long totalSeconds = ms / 1000;
        long hours = totalSeconds / 3600;
        long minutes = (totalSeconds % 3600) / 60;
        long seconds = totalSeconds % 60;
        if (hours > 0) {
            return String.format(Locale.getDefault(), "%d:%02d:%02d", hours, minutes, seconds);
        }
        return String.format(Locale.getDefault(), "%d:%02d", minutes, seconds);
    }

    private String formatTime(long millis) {
        long totalSeconds = millis / 1000;
        long minutes = totalSeconds / 60;
        long seconds = totalSeconds % 60;
        return String.format(Locale.getDefault(), "%d:%02d", minutes, seconds);
    }

    /**
     * Lädt das Album-Cover mit Glide.
     * Zeigt den Platzhalter wenn kein Cover vorhanden oder das Laden fehlschlägt.
     */
    private void updateAlbumArt(TrackSelector.TrackInfo track) {
        Uri artUri = track != null ? track.getAlbumArtUri() : null;
        Glide.with(this)
                .load(artUri)
                .placeholder(R.drawable.ic_album_placeholder)
                .error(R.drawable.ic_album_placeholder)
                .transition(DrawableTransitionOptions.withCrossFade(300))
                .centerCrop()
                .into(ivAlbumArt);

        // Overlay-Bild ebenfalls aktualisieren falls es gerade sichtbar ist
        if (overlayAlbumArt.getVisibility() == View.VISIBLE) {
            Glide.with(this)
                    .load(artUri)
                    .placeholder(R.drawable.ic_album_placeholder)
                    .error(R.drawable.ic_album_placeholder)
                    .into(ivAlbumArtFull);
        }
    }

    // ===== Album-Art Vollbild-Overlay =====

    private void showAlbumArtOverlay() {
        // Aktuelles Bild in das Vollbild-View laden
        TrackSelector.TrackInfo track = (isBound && playbackService != null)
                ? playbackService.getCurrentTrack() : null;
        Uri artUri = track != null ? track.getAlbumArtUri() : null;

        Glide.with(this)
                .load(artUri)
                .placeholder(R.drawable.ic_album_placeholder)
                .error(R.drawable.ic_album_placeholder)
                .into(ivAlbumArtFull);

        // Einblenden mit Fade-Animation
        AlphaAnimation fadeIn = new AlphaAnimation(0f, 1f);
        fadeIn.setDuration(200);
        overlayAlbumArt.setVisibility(View.VISIBLE);
        overlayAlbumArt.startAnimation(fadeIn);
    }

    private void hideAlbumArtOverlay() {
        AlphaAnimation fadeOut = new AlphaAnimation(1f, 0f);
        fadeOut.setDuration(200);
        fadeOut.setAnimationListener(new Animation.AnimationListener() {
            @Override public void onAnimationStart(Animation a) {}
            @Override public void onAnimationRepeat(Animation a) {}
            @Override public void onAnimationEnd(Animation a) {
                overlayAlbumArt.setVisibility(View.GONE);
            }
        });
        overlayAlbumArt.startAnimation(fadeOut);
    }

    /** Zurück-Taste schließt zuerst das Overlay (falls offen). */
    @Override
    public void onBackPressed() {
        if (overlayAlbumArt != null && overlayAlbumArt.getVisibility() == View.VISIBLE) {
            hideAlbumArtOverlay();
        } else {
            super.onBackPressed();
        }
    }
}

package com.example.sleepplayer;

import android.media.AudioAttributes;
import android.media.AudioFormat;
import android.media.AudioTrack;
import android.os.Handler;
import android.os.Looper;
import android.util.Log;

import java.util.Arrays;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

/**
 * Steuert die 4-7-8 Atemübung.
 *
+ * Ablauf:
 *   1. Intro-Dreiklang (C-Dur Arpeggio + Akkord)
 *   2. 5 Sekunden Pause zum Einrichten
 *   3. Einatmen  – hoher Ton  (C5, 528 Hz) – 4 s
 *   4. Halten    – mittlerer Ton (G4, 396 Hz) – 7 s
 *   5. Ausatmen  – tiefer Ton (C4, 264 Hz) – 8 s
 *   → Schritt 3–5 wiederholen bis 5 Minuten vergangen
 *   6. Abschluss-Dreiklang (Arpeggio + Akkord)
 *   7. Callback → PlaybackService wechselt in Schlafmodus
 *
 * Töne: Sinuswelle mit Obertönen (Singing-Bowl-Charakter),
 *       exponentieller Decay + zwei Sekundenechos.
 */
public class MeditationController {

    private static final String TAG = "MeditationController";

    private static final int  SAMPLE_RATE            = 22050; // 44100/2 – reicht für 264–528 Hz, 4× schnellere Berechnung
    private static final long MEDITATION_DURATION_MS = 5 * 60 * 1000L;

    // --- Frequenzen Atem-Phasen ---
    private static final float FREQ_INHALE = 528f;  // C5 – hoch  (einatmen)
    private static final float FREQ_HOLD   = 396f;  // G4 – mittel (halten)
    private static final float FREQ_EXHALE = 264f;  // C4 – tief  (ausatmen)

    // --- C-Dur Dreiklang (Intro + Abschluss) ---
    private static final float FREQ_C4 = 264f;
    private static final float FREQ_E4 = 330f;
    private static final float FREQ_G4 = 396f;

    // --- Phasendauern ---
    public static final long DUR_INHALE_MS = 4_000L;
    public static final long DUR_HOLD_MS   = 7_000L;
    public static final long DUR_EXHALE_MS = 8_000L;

    /** Gesamtpufferlänge inkl. Echo-Reflexionen. Kurz genug für schnelle Berechnung. */
    private static final int TONE_TOTAL_MS = 2_500;

    private static final double ECHO_AMP_1 = 0.38;
    private static final double ECHO_AMP_2 = 0.16;

    /**
     * Basis-Abklingkonstante (wird pro Frequenz skaliert).
     * Tiefe Töne klingen länger nach (wie Gitarren-Bassaiten).
     */
    private static final double DECAY_K_BASE = 1.6;

    // --- Öffentliche Typen ---

    public enum Phase { INHALE, HOLD, EXHALE, FINISHED }

    public interface MeditationCallback {
        void onPhaseChanged(Phase phase, int cycleNumber);
        void onMeditationFinished();
    }

    // --- Felder ---

    private final MeditationCallback callback;
    private final Handler             handler       = new Handler(Looper.getMainLooper());
    // CachedThreadPool: jeder Ton bekommt seinen eigenen Thread → kein Stau durch Thread.sleep
    private final ExecutorService     audioExecutor = Executors.newCachedThreadPool();

    private volatile boolean running     = false;
    private long             startTimeMs = 0;
    private int              cycleCount  = 0;
    private float            volume      = 0.5f;

    /** Aktuell spielende AudioTracks – werden bei stop() sofort gestoppt. */
    private final CopyOnWriteArrayList<AudioTrack> activeTracks = new CopyOnWriteArrayList<>();

    /**
     * Cache für vorberechnete Samples (Key = Frequenz-Array als String).
     * Verhindert wiederholte schwere Berechnung bei jedem Ton-Aufruf.
     */
    private final ConcurrentHashMap<String, short[]> sampleCache = new ConcurrentHashMap<>();

    // ===== Konstruktor =====

    public MeditationController(MeditationCallback callback) {
        this.callback = callback;
    }

    // ===== Öffentliche API =====

    /** Startet die Atemübung: Samples vorberechnen → Intro → 5 s Pause → erste Atemphase. */
    public void start(float vol) {
        if (running) return;
        this.volume = Math.max(0.05f, Math.min(1.0f, vol));
        running     = true;
        startTimeMs = System.currentTimeMillis();
        cycleCount  = 0;
        sampleCache.clear();
        Log.d(TAG, "Meditation gestartet (volume=" + this.volume + ")");

        // Alle benötigten Samples VORAB auf einem Background-Thread berechnen,
        // damit die Wiedergabe danach sofort und ohne Verzögerung starten kann.
        audioExecutor.execute(() -> {
            Log.d(TAG, "Vorberechnung der Samples...");
            cachedSamples(FREQ_C4);
            cachedSamples(FREQ_E4);
            cachedSamples(FREQ_G4);
            cachedSamples(FREQ_INHALE);
            cachedSamples(FREQ_HOLD);
            cachedSamples(FREQ_EXHALE);
            cachedChordSamples(new float[]{FREQ_C4, FREQ_E4, FREQ_G4});
            Log.d(TAG, "Vorberechnung abgeschlossen");

            // Intro auf dem Main-Thread starten (Samples sind jetzt im Cache)
            handler.post(() -> {
                if (!running) return;
                playTone(FREQ_C4);
                handler.postDelayed(() -> playTone(FREQ_E4),                                  600);
                handler.postDelayed(() -> playTone(FREQ_G4),                                1_200);
                handler.postDelayed(() -> playChord(new float[]{FREQ_C4, FREQ_E4, FREQ_G4}), 2_000);
                handler.postDelayed(this::scheduleInhale,                                   5_000);
            });
        });
    }

    /** Stoppt die Übung sofort und bricht alle laufenden Töne ab. */
    public void stop() {
        Log.d(TAG, "Meditation gestoppt");
        running = false;
        handler.removeCallbacksAndMessages(null);
        // Alle aktiven AudioTracks sofort stoppen
        for (AudioTrack track : activeTracks) {
            try { track.stop(); } catch (Exception ignored) {}
            try { track.release(); } catch (Exception ignored) {}
        }
        activeTracks.clear();
    }

    /** Gibt zurück ob die Übung gerade läuft. */
    public boolean isRunning() {
        return running;
    }

    /** Gesamtdauer eines Zyklus in ms. */
    public static long getCycleDurationMs() {
        return DUR_INHALE_MS + DUR_HOLD_MS + DUR_EXHALE_MS;
    }

    // ===== Private Scheduling-Methoden =====

    /** Einatmen – hoher Ton (C5), 4 s. */
    private void scheduleInhale() {
        if (!running) return;
        if (System.currentTimeMillis() - startTimeMs >= MEDITATION_DURATION_MS) {
            playEndSequence();
            return;
        }
        cycleCount++;
        Log.d(TAG, "Zyklus " + cycleCount + " – Einatmen");
        playTone(FREQ_INHALE);
        if (callback != null) callback.onPhaseChanged(Phase.INHALE, cycleCount);
        handler.postDelayed(this::scheduleHold, DUR_INHALE_MS);
    }

    /** Halten – mittlerer Ton (G4), 7 s. */
    private void scheduleHold() {
        if (!running) return;
        Log.d(TAG, "Zyklus " + cycleCount + " – Halten");
        playTone(FREQ_HOLD);
        if (callback != null) callback.onPhaseChanged(Phase.HOLD, cycleCount);
        handler.postDelayed(this::scheduleExhale, DUR_HOLD_MS);
    }

    /** Ausatmen – tiefer Ton (C4), 8 s. */
    private void scheduleExhale() {
        if (!running) return;
        Log.d(TAG, "Zyklus " + cycleCount + " – Ausatmen");
        playTone(FREQ_EXHALE);
        if (callback != null) callback.onPhaseChanged(Phase.EXHALE, cycleCount);
        handler.postDelayed(this::scheduleInhale, DUR_EXHALE_MS);
    }

    /** Abschluss: Arpeggio + Akkord, dann Callback → Schlafmodus. */
    private void playEndSequence() {
        running = false;
        Log.d(TAG, "Abschluss-Sequenz");

        playTone(FREQ_C4);
        handler.postDelayed(() -> playTone(FREQ_E4),                              600);
        handler.postDelayed(() -> playTone(FREQ_G4),                            1_200);
        handler.postDelayed(() -> playChord(new float[]{FREQ_C4, FREQ_E4, FREQ_G4}), 2_000);

        // Callback nach Arpeggio + Akkord-Ausklingen
        handler.postDelayed(() -> {
            if (callback != null) {
                callback.onPhaseChanged(Phase.FINISHED, cycleCount);
                callback.onMeditationFinished();
            }
        }, 5_500);
    }

    // ===== Ton-Generierung =====

    private void playTone(float frequency) {
        final float vol = this.volume;
        audioExecutor.execute(() -> playPcm(cachedSamples(frequency), vol));
    }

    private void playChord(float[] frequencies) {
        final float vol = this.volume;
        audioExecutor.execute(() -> playPcm(cachedChordSamples(frequencies), vol));
    }

    /** Gibt gecachte Samples für einen einzelnen Ton zurück (berechnet bei Bedarf). */
    private short[] cachedSamples(float frequency) {
        String key = String.valueOf(frequency);
        return sampleCache.computeIfAbsent(key,
                k -> generateChordSamples(new float[]{frequency}));
    }

    /** Gibt gecachte Samples für einen Akkord zurück (berechnet bei Bedarf). */
    private short[] cachedChordSamples(float[] frequencies) {
        String key = Arrays.toString(frequencies);
        return sampleCache.computeIfAbsent(key, k -> generateChordSamples(frequencies));
    }

    /** Gemeinsame AudioTrack-Wiedergabe. */
    private void playPcm(short[] samples, float vol) {
        AudioTrack track = null;
        try {
            int numSamples = samples.length;
            int minBuf = AudioTrack.getMinBufferSize(SAMPLE_RATE,
                    AudioFormat.CHANNEL_OUT_MONO, AudioFormat.ENCODING_PCM_16BIT);

            track = new AudioTrack.Builder()
                    .setAudioAttributes(new AudioAttributes.Builder()
                            .setUsage(AudioAttributes.USAGE_MEDIA)
                            .setContentType(AudioAttributes.CONTENT_TYPE_MUSIC)
                            .build())
                    .setAudioFormat(new AudioFormat.Builder()
                            .setSampleRate(SAMPLE_RATE)
                            .setEncoding(AudioFormat.ENCODING_PCM_16BIT)
                            .setChannelMask(AudioFormat.CHANNEL_OUT_MONO)
                            .build())
                    .setBufferSizeInBytes(Math.max(minBuf, numSamples * 2))
                    .setTransferMode(AudioTrack.MODE_STATIC)
                    .build();

            track.write(samples, 0, numSamples);
            track.setVolume(vol);
            activeTracks.add(track);
            track.play();
            Thread.sleep(TONE_TOTAL_MS + 80L);

        } catch (InterruptedException e) {
            Thread.currentThread().interrupt(); // Abbruch durch stop() – kein Fehler
        } catch (Exception e) {
            Log.e(TAG, "Fehler bei PCM-Wiedergabe", e);
        } finally {
            if (track != null) {
                activeTracks.remove(track);
                try { track.stop(); } catch (Exception ignored) {}
                try { track.release(); } catch (Exception ignored) {}
            }
        }
    }

    /**
     * Erzeugt akustisch-gitarrenartige PCM-Samples für einen oder mehrere Töne.
     *
     * Klang-Modell (angelehnt an Akustikgitarre / gezupfte Saite):
     *   - 6 Obertöne mit abnehmenden Amplituden (0.42, 0.24, 0.14, 0.09, 0.06, 0.05)
     *   - Höhere Obertöne klingen schneller ab (partialDecay × n)
     *   - Frequenzabhängiger Gesamt-Decay: tiefe Töne länger (Bassaite), hohe kürzer
     *
     * Echo-Modell (4 unregelmäßige Reflexionen, natürlicher Raumklang):
     *   +750 ms  × 0.42  – erste starke Reflexion
     *   +1550 ms × 0.22  – zweite Reflexion
     *   +2300 ms × 0.10  – dritte Reflexion (ferne Wand)
     *   +3100 ms × 0.04  – viertes, kaum hörbares Nachklingen
     */
    private static short[] generateChordSamples(float[] frequencies) {
        int      numSamples    = SAMPLE_RATE * TONE_TOTAL_MS / 1000;
        double[] buf           = new double[numSamples];
        int      attackSamples = (int) (SAMPLE_RATE * 0.008); // 8 ms – Gitarren-Anschlag

        // Echo-Abstände (3 Reflexionen – ausreichend für natürlichen Klang)
        int[]    echoOffsets = {
                0,
                (int) (SAMPLE_RATE * 0.600),
                (int) (SAMPLE_RATE * 1.300)
        };
        double[] echoAmps = {1.0, ECHO_AMP_1, ECHO_AMP_2};

        // 4 Obertöne (reicht für warmen Gitarren-Charakter, deutlich schneller)
        double[] harmonicAmps = {0.45, 0.28, 0.16, 0.11};

        for (float freq : frequencies) {
            // Frequenzabhängiger Decay: tiefe Töne langsamer (Bassaite ≈ 1.0), hohe schneller
            // Referenz: 264 Hz → k=1.0 × BASE; 528 Hz → k=1.6 × BASE
            double freqFactor = 0.7 + (freq / 264f) * 0.45;
            double decayK     = DECAY_K_BASE * freqFactor;

            for (int e = 0; e < echoOffsets.length; e++) {
                int    offset   = echoOffsets[e];
                double echoAmp  = echoAmps[e];

                for (int i = offset; i < numSamples; i++) {
                    int    li    = i - offset;
                    double t     = (double) li / SAMPLE_RATE;
                    double tDecay = Math.max(0, t - (double) attackSamples / SAMPLE_RATE);

                    // Globale Hüllkurve: kurzes Attack → exp. Decay
                    double env;
                    if (li < attackSamples) {
                        env = (double) li / attackSamples;
                    } else {
                        env = Math.exp(-decayK * tDecay);
                    }

                    // Oberton-Summe: jeder Partial klingt etwas schneller ab (× 1 + n*0.4)
                    double wave = 0.0;
                    for (int n = 1; n <= harmonicAmps.length; n++) {
                        double partialDecay = Math.exp(-decayK * tDecay * (1.0 + (n - 1) * 0.4));
                        double angle = 2.0 * Math.PI * freq * n * t;
                        wave += harmonicAmps[n - 1] * Math.sin(angle) * partialDecay;
                    }

                    buf[i] += wave * env * echoAmp;
                }
            }
        }

        // Normalisieren (verhindert Clipping bei Akkorden / vielen Echos)
        double maxVal = 0.0;
        for (double v : buf) if (Math.abs(v) > maxVal) maxVal = Math.abs(v);
        double scale = (maxVal > 0.001) ? (0.90 / maxVal) : 0.90;

        short[] samples = new short[numSamples];
        for (int i = 0; i < numSamples; i++) {
            samples[i] = (short) (buf[i] * scale * Short.MAX_VALUE);
        }
        return samples;
    }
}

package com.example.sleepplayer;

import android.content.Context;
import android.media.AudioAttributes;
import android.media.SoundPool;
import android.os.Handler;
import android.os.Looper;
import android.util.Log;

/**
 * Steuert die 4-7-8 Atemübung mit aufgenommenen Audio-Samples.
 *
 * Ablauf:
 *   1. Intro-Chord (meditation_chord) + 5 s Einrichtungspause
 *   2. Einatmen  (meditation_inhale) – 4 s
 *   3. Halten    (meditation_hold)   – 7 s
 *   4. Ausatmen  (meditation_exhale) – 8 s
 *   → Schritt 2–4 wiederholen bis 5 Minuten vergangen
 *   5. Abschluss-Chord (meditation_chord)
 *   6. Callback → PlaybackService wechselt in Schlafmodus
 *
 * Samples müssen in res/raw/ abgelegt werden:
 *   meditation_chord.wav   – Begrüßungs-/Abschluss-Akkord
 *   meditation_inhale.wav  – Ton für Einatmen
 *   meditation_hold.wav    – Ton für Halten
 *   meditation_exhale.wav  – Ton für Ausatmen
 *
 * Solange Dateien fehlen, läuft die Übung ohne Ton (nur Callbacks/Timing).
 */
public class MeditationController {

    private static final String TAG = "MeditationController";

    private static final long MEDITATION_DURATION_MS = 5 * 60 * 1000L;

    public static final long DUR_INHALE_MS = 4_000L;
    public static final long DUR_HOLD_MS   = 7_000L;
    public static final long DUR_EXHALE_MS = 8_000L;

    /** Pause nach dem Intro-Chord, bevor der erste Atemzyklus beginnt. */
    private static final long INTRO_PAUSE_MS = 5_000L;

    /** Pause nach dem Abschluss-Chord, bevor der Finished-Callback kommt. */
    private static final long OUTRO_PAUSE_MS = 3_000L;

    // --- Öffentliche Typen ---

    public enum Phase { INHALE, HOLD, EXHALE, FINISHED }

    public interface MeditationCallback {
        void onPhaseChanged(Phase phase, int cycleNumber);
        void onMeditationFinished();
    }

    // --- Felder ---

    private final Context            context;
    private final MeditationCallback callback;
    private final Handler            handler = new Handler(Looper.getMainLooper());

    private SoundPool soundPool;
    private int       idChord   = 0;
    private int       idInhale  = 0;
    private int       idHold   = 0;
    private int       idExhale  = 0;

    private volatile boolean running     = false;
    private long             startTimeMs = 0;
    private int              cycleCount  = 0;
    private float            volume      = 0.5f;

    // ===== Konstruktor =====

    public MeditationController(Context context, MeditationCallback callback) {
        this.context  = context.getApplicationContext();
        this.callback = callback;
        initSoundPool();
    }

    // ===== Initialisierung =====

    private void initSoundPool() {
        AudioAttributes attrs = new AudioAttributes.Builder()
                .setUsage(AudioAttributes.USAGE_MEDIA)
                .setContentType(AudioAttributes.CONTENT_TYPE_MUSIC)
                .build();

        soundPool = new SoundPool.Builder()
                .setMaxStreams(2)
                .setAudioAttributes(attrs)
                .build();

        // Samples laden – schlägt lautlos fehl wenn Datei noch nicht existiert
        idChord  = safeLoad(R.raw.meditation_chord);
        idInhale = safeLoad(R.raw.meditation_inhale);
        idHold   = safeLoad(R.raw.meditation_hold);
        idExhale = safeLoad(R.raw.meditation_exhale);

        Log.d(TAG, "SoundPool – chord=" + idChord + " inhale=" + idInhale
                + " hold=" + idHold + " exhale=" + idExhale);
    }

    /** Lädt ein Raw-Sample sicher (gibt 0 zurück wenn nicht vorhanden). */
    private int safeLoad(int resId) {
        try {
            return soundPool.load(context, resId, 1);
        } catch (Exception e) {
            Log.w(TAG, "Sample nicht gefunden resId=" + resId + " – wird übersprungen");
            return 0;
        }
    }

    // ===== Öffentliche API =====

    /** Startet die Atemübung. */
    public void start(float vol) {
        if (running) return;
        this.volume = Math.max(0.05f, Math.min(1.0f, vol));
        running     = true;
        startTimeMs = System.currentTimeMillis();
        cycleCount  = 0;
        Log.d(TAG, "Meditation gestartet (volume=" + this.volume + ")");

        playSound(idChord);
        handler.postDelayed(this::scheduleInhale, INTRO_PAUSE_MS);
    }

    /** Stoppt die Übung sofort. */
    public void stop() {
        Log.d(TAG, "Meditation gestoppt");
        running = false;
        handler.removeCallbacksAndMessages(null);
        if (soundPool != null) soundPool.autoPause();
    }

    /** Gibt zurück ob die Übung gerade läuft. */
    public boolean isRunning() {
        return running;
    }

    /** Gesamtdauer eines Zyklus in ms. */
    public static long getCycleDurationMs() {
        return DUR_INHALE_MS + DUR_HOLD_MS + DUR_EXHALE_MS;
    }

    /** Gibt SoundPool-Ressourcen frei. */
    public void release() {
        stop();
        if (soundPool != null) {
            soundPool.release();
            soundPool = null;
        }
    }

    // ===== Private Scheduling-Methoden =====

    private void scheduleInhale() {
        if (!running) return;
        if (System.currentTimeMillis() - startTimeMs >= MEDITATION_DURATION_MS) {
            playEndSequence();
            return;
        }
        cycleCount++;
        Log.d(TAG, "Zyklus " + cycleCount + " – Einatmen");
        playSound(idInhale);
        if (callback != null) callback.onPhaseChanged(Phase.INHALE, cycleCount);
        handler.postDelayed(this::scheduleHold, DUR_INHALE_MS);
    }

    private void scheduleHold() {
        if (!running) return;
        Log.d(TAG, "Zyklus " + cycleCount + " – Halten");
        playSound(idHold);
        if (callback != null) callback.onPhaseChanged(Phase.HOLD, cycleCount);
        handler.postDelayed(this::scheduleExhale, DUR_HOLD_MS);
    }

    private void scheduleExhale() {
        if (!running) return;
        Log.d(TAG, "Zyklus " + cycleCount + " – Ausatmen");
        playSound(idExhale);
        if (callback != null) callback.onPhaseChanged(Phase.EXHALE, cycleCount);
        handler.postDelayed(this::scheduleInhale, DUR_EXHALE_MS);
    }

    private void playEndSequence() {
        running = false;
        Log.d(TAG, "Abschluss-Sequenz");
        playSound(idChord);
        handler.postDelayed(() -> {
            if (callback != null) {
                callback.onPhaseChanged(Phase.FINISHED, cycleCount);
                callback.onMeditationFinished();
            }
        }, OUTRO_PAUSE_MS);
    }

    // ===== Ton-Wiedergabe =====

    private void playSound(int soundId) {
        if (soundPool == null || soundId == 0) return;
        soundPool.play(soundId, volume, volume, 1, 0, 1.0f);
    }
}

package com.example.sleepplayer;

import android.app.Notification;
import android.app.Service;
import android.content.Intent;
import android.media.AudioAttributes;
import android.media.AudioFocusRequest;
import android.media.AudioManager;
import android.media.MediaPlayer;
import android.os.Binder;
import android.os.CountDownTimer;
import android.os.Handler;
import android.os.IBinder;
import android.os.Looper;
import android.os.PowerManager;
import android.support.v4.media.MediaMetadataCompat;
import android.support.v4.media.session.MediaSessionCompat;
import android.support.v4.media.session.PlaybackStateCompat;
import android.util.Log;

import androidx.annotation.Nullable;
import androidx.media.session.MediaButtonReceiver;

import java.io.IOException;
import java.util.List;
import java.util.concurrent.ExecutorService;import java.util.concurrent.Executors;

/**
 * Foreground-Service für die Audio-Wiedergabe.
 *
 * Verantwortlich für:
 * - MediaPlayer Verwaltung
 * - MediaSession (Kopfhörer-Tasten)
 * - Sleep-Timer (CountDownTimer)
 * - Audio Focus
 * - WakeLock
 * - Foreground Notification
 */
public class PlaybackService extends Service {

    private static final String TAG = "PlaybackService";

    /** Dauer des Fade-outs in Millisekunden (letzte 60 Sekunden vor Timer-Ende). */
    private static final long FADE_OUT_DURATION_MS = 60_000L;

    // Binder für Activity-Kommunikation
    private final IBinder binder = new LocalBinder();

    /** Hintergrund-Thread für MediaStore-Abfragen (verhindert Main-Thread I/O / ANR). */
    private final ExecutorService ioExecutor = Executors.newSingleThreadExecutor();
    /** Handler zum Zurückwechseln auf den Main-Thread nach I/O. */
    private final Handler mainHandler = new Handler(Looper.getMainLooper());

    private MediaPlayer mediaPlayer;
    private MediaSessionCompat mediaSession;
    private AudioManager audioManager;
    private AudioFocusRequest audioFocusRequest;
    private TrackSelector trackSelector;
    private PrefsManager prefsManager;

    private CountDownTimer sleepTimer;
    private long timerMillisRemaining = 0;
    private int timerTotalMinutes = 30;
    private boolean isTimerRunning = false;

    private float currentVolume = 0.15f;
    private boolean isPlaying = false;
    private boolean isRandomMode = true;

    /**
     * Generations-Zähler zur Vermeidung von Race-Conditions beim asynchronen Track-Laden.
     *
     * Problem ohne diesen Zähler:
     *   1. Track A läuft zu Ende → onCompletion → startRandomPlayback() startet IO-Thread
     *   2. Nutzer wählt währenddessen Track B aus → playTrackInternal(B) läuft sofort
     *   3. IO-Thread fertig → mainHandler.post(playTrackInternal(random)) → überschreibt B!
     *
     * Lösung: playTrackInternal() inkrementiert den Zähler. Der async-Callback prüft
     * ob der Zähler noch passt; falls nicht, wird der veraltete Aufruf verworfen.
     */
    private int playbackGeneration = 0;

    // Fade-out Zustand
    private boolean isFadingOut = false;
    private float volumeBeforeFade = 0f;

    /**
     * Normalisierungs-Gain des aktuell spielenden Tracks (1.0 = keine Änderung).
     * Wird in playTrackInternal() gesetzt.
     */
    private float currentTrackGain = 1.0f;

    /**
     * Sektionsweise Gain-Daten für den aktuellen Track.
     * float[2] = [sectionStartMs, gainMultiplier]. null = keine Sektionsdaten.
     */
    private List<float[]> currentSectionalGains = null;

    /** Handler-Runnable zum periodischen Anpassen des Sektions-Gains. */
    private static final int SECTIONAL_GAIN_INTERVAL_MS = 2000;
    private final Runnable sectionalGainRunnable = new Runnable() {
        @Override
        public void run() {
            applySectionalGain();
            if (isPlaying && currentSectionalGains != null) {
                mainHandler.postDelayed(this, SECTIONAL_GAIN_INTERVAL_MS);
            }
        }
    };

    /** Normalisierungs-Daten (Referenz-Track + Gain-Offsets). */
    private NormalizationStore normalizationStore;

    /**
     * WakeLock auf Service-Ebene – hält die CPU wach, damit der Service im
     * Hintergrund nicht vom System in einen Zustand versetzt wird, in dem er
     * keine Intents mehr empfangen kann.
     *
     * PARTIAL_WAKE_LOCK: CPU läuft, Bildschirm darf aus → batterieschonend.
     * Wird bei echter Wiedergabe und im Schlafmodus (Timer abgelaufen, aber Service
     * noch aktiv) gehalten; wird nur in stopPlayback() / onDestroy() freigegeben.
     */
    private PowerManager.WakeLock serviceWakeLock;

    private TrackSelector.TrackInfo currentTrack;

    /** Sprachsynthese für Zeitansage beim Timer-Start. */
    private TtsHelper ttsHelper;

    /** Steuerung der 4-7-8 Atemübung. */
    private MeditationController meditationController;

    // Callback-Interface für UI-Updates
    private PlaybackCallback callback;

    public interface PlaybackCallback {
        void onTrackChanged(TrackSelector.TrackInfo track);
        void onPlaybackStateChanged(boolean isPlaying);
        void onTimerTick(long millisRemaining);
        void onTimerFinished();
        /** Wird aufgerufen wenn der Meditations-Modus ein-/ausgeschaltet wird. */
        default void onMeditationStateChanged(boolean active, MeditationController.Phase phase, int cycle) {}
    }

    public class LocalBinder extends Binder {
        public PlaybackService getService() {
            return PlaybackService.this;
        }
    }

    @Override
    public void onCreate() {
        super.onCreate();
        Log.d(TAG, "Service created (instance=" + System.identityHashCode(this) + ")");

        prefsManager = new PrefsManager(this);
        trackSelector = new TrackSelector(this);
        audioManager = (AudioManager) getSystemService(AUDIO_SERVICE);
        normalizationStore = new NormalizationStore(this);

        // Meditations-Controller initialisieren
        meditationController = new MeditationController(new MeditationController.MeditationCallback() {
            @Override
            public void onPhaseChanged(MeditationController.Phase phase, int cycle) {
                Log.d(TAG, "Meditation Phase: " + phase + " Zyklus " + cycle);
                if (callback != null) {
                    callback.onMeditationStateChanged(true, phase, cycle);
                }
            }
            @Override
            public void onMeditationFinished() {
                Log.d(TAG, "Meditation beendet");
                if (callback != null) {
                    callback.onMeditationStateChanged(false,
                            MeditationController.Phase.FINISHED, 0);
                }
                // Automatisch zurück in den normalen Schlafmodus wechseln
                showSleepModeNotification();
            }
        });

        // Notification Channel erstellen
        NotificationHelper.createChannel(this);

        // Service-WakeLock initialisieren (noch nicht acquiren)
        PowerManager pm = (PowerManager) getSystemService(POWER_SERVICE);
        serviceWakeLock = pm.newWakeLock(
                PowerManager.PARTIAL_WAKE_LOCK, "SleepPlayer:ServiceWakeLock");
        serviceWakeLock.setReferenceCounted(false);

        // MediaSession erstellen (MUSS vor startForeground() stehen!)
        mediaSession = new MediaSessionCompat(this, "SleepPlayer");
        mediaSession.setCallback(new MediaSessionCallback(this));
        mediaSession.setFlags(
                MediaSessionCompat.FLAG_HANDLES_MEDIA_BUTTONS
                        | MediaSessionCompat.FLAG_HANDLES_TRANSPORT_CONTROLS);
        mediaSession.setActive(true);

        // Initialen PlaybackState setzen – ohne diesen ignoriert Android
        // die MediaSession beim allerersten Kopfhörer-Tastendruck
        updatePlaybackState(PlaybackStateCompat.STATE_STOPPED);

        // Sofort als Foreground-Service starten – stellt sicher dass die MediaSession
        // von Anfang an Kopfhörer-Tasten empfängt, auch beim allerersten App-Start
        // ohne vorherigen Track. Der Service bleibt so immer erreichbar.
        // WICHTIG: erst NACH mediaSession-Initialisierung aufrufen!
        Notification initialNotification = NotificationHelper.buildNotification(
                this, mediaSession, getString(R.string.app_name), false);
        startForeground(NotificationHelper.NOTIFICATION_ID, initialNotification);

        // Audio Focus Request
        AudioAttributes audioAttributes = new AudioAttributes.Builder()
                .setUsage(AudioAttributes.USAGE_MEDIA)
                .setContentType(AudioAttributes.CONTENT_TYPE_MUSIC)
                .build();

        audioFocusRequest = new AudioFocusRequest.Builder(AudioManager.AUDIOFOCUS_GAIN)
                .setAudioAttributes(audioAttributes)
                .setOnAudioFocusChangeListener(this::onAudioFocusChange)
                .build();

        // Gespeicherte Lautstärke laden
        int savedProgress = prefsManager.getVolume();
        currentVolume = VolumeHelper.progressToVolume(savedProgress);

        // Gespeicherten Wiedergabe-Modus laden
        isRandomMode = prefsManager.isRandomMode();

        // Gespeicherte Timer-Dauer laden
        timerTotalMinutes = prefsManager.getTimerMinutes();

        // TTS initialisieren (asynchron – bereit bevor der erste Timer gestartet wird)
        ttsHelper = new TtsHelper(this);

        // Track-Liste im Hintergrund vorladen, damit beim ersten Abspielen
        // KEIN MediaStore-Query auf dem Main-Thread nötig ist (ANR-Prävention).
        ioExecutor.execute(() -> {
            List<TrackSelector.TrackInfo> tracks = trackSelector.getAllTracks();
            Log.d(TAG, "Track-Cache vorgeladen: " + tracks.size() + " Titel");
        });
    }

    @Override
    public int onStartCommand(Intent intent, int flags, int startId) {
        if (intent != null) {
            String action = intent.getAction();

            if (NotificationHelper.ACTION_PLAY_PAUSE.equals(action)) {
                togglePlayPause();
            } else if (NotificationHelper.ACTION_STOP.equals(action)) {
                stopPlayback();
            } else if (NotificationHelper.ACTION_DISMISS.equals(action)) {
                // Nutzer hat die Sleep-Mode-Notification weggewischt → Service vollständig beenden
                Log.d(TAG, "ACTION_DISMISS empfangen – Service wird beendet");
                stopPlayback();
            } else {
                // Könnte ein MediaButton-Intent sein
                MediaButtonReceiver.handleIntent(mediaSession, intent);
            }
        }

        return START_STICKY;
    }

    @Nullable
    @Override
    public IBinder onBind(Intent intent) {
        return binder;
    }

    @Override
    public void onDestroy() {
        Log.d(TAG, "Service destroyed (instance=" + System.identityHashCode(this) + ")");
        ioExecutor.shutdownNow();
        stopTimerInternal();
        releaseMediaPlayer();
        if (ttsHelper != null) {
            ttsHelper.release();
            ttsHelper = null;
        }
        if (meditationController != null) {
            meditationController.stop();
            meditationController = null;
        }
        if (mediaSession != null) {
            mediaSession.setActive(false);
            mediaSession.release();
        }
        abandonAudioFocus();
        releaseServiceWakeLock();
        super.onDestroy();
    }

    // ===== Öffentliche Methoden für Activity und MediaSessionCallback =====

    public void setCallback(PlaybackCallback callback) {
        this.callback = callback;
    }

    /**
     * Spielt den nächsten Titel ab – zufällig oder aktuellen wiederholen,
     * je nach aktuellem Modus.
     *
     * WICHTIG: Die MediaStore-Abfrage läuft auf einem Hintergrund-Thread,
     * um ANR auf dem Main-Thread zu verhindern.
     */
    public void startRandomPlayback() {
        Log.d(TAG, "startRandomPlayback() – isRandomMode=" + isRandomMode
                + ", currentTrack=" + (currentTrack != null ? currentTrack.title : "null"));
        if (isRandomMode) {
            // Generation zum Zeitpunkt dieses Aufrufs merken
            final int generation = playbackGeneration;
            ioExecutor.execute(() -> {
                TrackSelector.TrackInfo track = trackSelector.getNextTrack();
                Log.d(TAG, "Nächster Track ausgewählt: "
                        + (track != null ? track.title : "keiner!"));
                mainHandler.post(() -> {
                    // Nur abspielen wenn kein direkter Track-Wechsel dazwischengekommen ist
                    if (generation != playbackGeneration) {
                        Log.d(TAG, "startRandomPlayback: Generation veraltet – abgebrochen "
                                + "(war=" + generation + ", aktuell=" + playbackGeneration + ")");
                        return;
                    }
                    if (track != null) {
                        playTrackInternal(track);
                    } else {
                        Log.w(TAG, "Keine Tracks verfügbar – Wiedergabe gestoppt");
                    }
                });
            });
        } else {
            repeatCurrentTrack();
        }
    }

    /**
     * Wiederholt den aktuellen Track (Einzeltitel-Wiederholung).
     * Falls noch kein Track gespielt wurde, startet einen zufälligen.
     */
    private void repeatCurrentTrack() {
        if (currentTrack != null) {
            Log.d(TAG, "repeatCurrentTrack: " + currentTrack.title);
            playTrackInternal(currentTrack);
        } else {
            Log.d(TAG, "repeatCurrentTrack: kein aktueller Track – lade zufällig");
            final int generation = playbackGeneration;
            ioExecutor.execute(() -> {
                TrackSelector.TrackInfo track = trackSelector.getNextTrack();
                mainHandler.post(() -> {
                    if (generation != playbackGeneration) {
                        Log.d(TAG, "repeatCurrentTrack: Generation veraltet – abgebrochen");
                        return;
                    }
                    if (track != null) {
                        playTrackInternal(track);
                    }
                });
            });
        }
    }

    /**
     * Spielt einen bestimmten Track ab (z.B. direkte Selektion aus der Liste).
     * Wenn der Player gerade nicht läuft (neuer Start), wird zuerst die Uhrzeit angesagt.
     * Wenn bereits ein Track läuft (Wechsel), startet der neue Track sofort ohne Ansage.
     */
    public void playTrack(TrackSelector.TrackInfo track) {
        if (!isPlaying) {
            speakTimeAndThen(() -> playTrackInternal(track));
        } else {
            playTrackInternal(track);
        }
    }

    /**
     * Interne Wiedergabe-Implementierung.
     *
     * Verwendet eine lokale 'player'-Variable anstelle von 'mediaPlayer',
     * um veraltete Callbacks (von einem bereits ersetzten MediaPlayer) sicher
     * zu erkennen und zu ignorieren.
     */
    private void playTrackInternal(TrackSelector.TrackInfo track) {
        if (track == null) {
            Log.w(TAG, "playTrackInternal: track ist null, abgebrochen");
            return;
        }
        // Generation inkrementieren → macht alle laufenden async-Anfragen ungültig
        playbackGeneration++;
        Log.d(TAG, "playTrackInternal: " + track.title + " / " + track.artist
                + " (generation=" + playbackGeneration + ")");

        // Audio Focus anfordern
        int result = audioManager.requestAudioFocus(audioFocusRequest);
        if (result != AudioManager.AUDIOFOCUS_REQUEST_GRANTED) {
            Log.w(TAG, "Audio Focus nicht erhalten – Wiedergabe abgebrochen");
            return;
        }

        // Service-WakeLock halten – verhindert, dass der Service vom System
        // "eingeschläfert" wird und keine Intents mehr empfangen kann
        acquireServiceWakeLock();

        // Alten Player stoppen und freigeben
        releaseMediaPlayer();

        // Normalisierungs-Gain für diesen Track laden
        currentTrackGain = normalizationStore.getGain(track.uri.toString());
        // Sektionsweise Gains laden (null wenn nicht vorhanden)
        currentSectionalGains = normalizationStore.getSectionalGains(track.uri.toString());
        mainHandler.removeCallbacks(sectionalGainRunnable);
        Log.d(TAG, "Track-Gain: " + currentTrackGain + "× für " + track.title
                + (currentSectionalGains != null ? " (" + currentSectionalGains.size() + " Sektionen)" : ""));

        try {
            MediaPlayer player = new MediaPlayer();
            mediaPlayer = player; // sofort setzen, damit Stale-Check funktioniert

            player.setAudioAttributes(
                    new AudioAttributes.Builder()
                            .setUsage(AudioAttributes.USAGE_MEDIA)
                            .setContentType(AudioAttributes.CONTENT_TYPE_MUSIC)
                            .build());
            player.setDataSource(this, track.uri);
            player.setWakeMode(this, PowerManager.PARTIAL_WAKE_LOCK);
            player.setVolume(effectiveVolume(currentVolume), effectiveVolume(currentVolume));

            player.setOnPreparedListener(mp -> {
                // Sicherheitscheck: Wurde dieser Player inzwischen ersetzt?
                if (mediaPlayer != player) {
                    Log.w(TAG, "onPrepared: Player wurde bereits ersetzt, ignoriere");
                    return;
                }
                Log.d(TAG, "onPrepared: starte '" + track.title + "'");
                mp.start();
                isPlaying = true;
                currentTrack = track;

                updatePlaybackState(PlaybackStateCompat.STATE_PLAYING);
                updateMediaMetadata(track);
                showNotification();

                if (callback != null) {
                    callback.onTrackChanged(track);
                    callback.onPlaybackStateChanged(true);
                }

                // Sektions-Gain-Handler starten falls Sektionsdaten vorhanden
                if (currentSectionalGains != null) {
                    mainHandler.postDelayed(sectionalGainRunnable, SECTIONAL_GAIN_INTERVAL_MS);
                }

                // Timer starten falls noch nicht läuft
                if (!isTimerRunning) {
                    Log.d(TAG, "Timer noch nicht aktiv – starte Timer");
                    startTimer(timerTotalMinutes);
                }
            });

            player.setOnCompletionListener(mp -> {
                // Sicherheitscheck: Wurde dieser Player inzwischen ersetzt?
                if (mediaPlayer != player) {
                    Log.w(TAG, "onCompletion: Player wurde bereits ersetzt, ignoriere");
                    return;
                }
                Log.d(TAG, "onCompletion: '" + track.title + "' fertig – nächster Track");
                startRandomPlayback();
            });

            player.setOnErrorListener((mp, what, extra) -> {
                Log.e(TAG, "MediaPlayer Fehler: what=" + what + " extra=" + extra
                        + " track='" + track.title + "'");
                if (mediaPlayer != player) {
                    Log.w(TAG, "onError: Player wurde bereits ersetzt, ignoriere");
                    return true;
                }
                // Bei Fehler: nächsten Track versuchen
                startRandomPlayback();
                return true;
            });

            Log.d(TAG, "prepareAsync() gestartet für: " + track.title);
            player.prepareAsync();

        } catch (IOException e) {
            Log.e(TAG, "IOException beim Laden: " + track.title, e);
            // Nächsten Track versuchen
            startRandomPlayback();
        } catch (Exception e) {
            Log.e(TAG, "Unerwarteter Fehler in playTrackInternal", e);
        }
    }

    /**
     * Toggle Play/Pause – wird von der Kopfhörer-Taste aufgerufen.
     * Spricht zuerst die aktuelle Uhrzeit an (passend zur Track-Lautstärke),
     * startet danach den Track bzw. setzt die Wiedergabe fort.
     */
    public void togglePlayPause() {
        Log.d(TAG, "togglePlayPause() – isPlaying=" + isPlaying
                + ", hasPlayer=" + (mediaPlayer != null)
                + ", currentTrack=" + (currentTrack != null ? currentTrack.title : "null"));

        // Wenn Meditation läuft → Pause = Meditation beenden, zurück in Schlafmodus
        if (isMeditating()) {
            Log.d(TAG, "togglePlayPause: Meditation läuft → stoppe Meditation");
            stopMeditation();
            return;
        }

        if (isPlaying) {
            pausePlayback();
        } else {
            if (mediaPlayer == null || currentTrack == null) {
                // Neuer Start: TTS → dann Track laden
                speakTimeAndThen(() -> {
                    startRandomPlayback();
                    // Timer startet in onPrepared falls noch nicht aktiv;
                    // hier sicherheitshalber auch direkt (doppelt-sicher):
                    if (!isTimerRunning) restartTimer();
                });
            } else {
                // Fortsetzen nach Pause: TTS → dann resume
                speakTimeAndThen(() -> {
                    resumePlayback();
                    restartTimer();
                });
            }
        }
    }

    /**
     * Spricht die aktuelle Uhrzeit (mit Track-Lautstärke) und ruft danach {@code action} aus.
     * Falls TTS deaktiviert oder nicht verfügbar, wird {@code action} sofort ausgeführt.
     */
    private void speakTimeAndThen(Runnable action) {
        if (ttsHelper != null && prefsManager.isTtsEnabled()) {
            ttsHelper.speakCurrentTime(currentVolume, action);
        } else {
            action.run();
        }
    }

    /**
     * Pausiert die Wiedergabe.
     */
    public void pausePlayback() {
        Log.d(TAG, "pausePlayback() – isPlaying=" + isPlaying);
        if (mediaPlayer != null && isPlaying) {
            try {
                mediaPlayer.pause();
            } catch (IllegalStateException e) {
                Log.e(TAG, "IllegalStateException in pausePlayback()", e);
                // Player in unerwartetem Zustand – freigeben
                releaseMediaPlayer();
            }
            isPlaying = false;
            updatePlaybackState(PlaybackStateCompat.STATE_PAUSED);
            showNotification();

            if (callback != null) {
                callback.onPlaybackStateChanged(false);
            }
        }
    }

    /**
     * Setzt die Wiedergabe fort.
     */
    public void resumePlayback() {
        Log.d(TAG, "resumePlayback() – isPlaying=" + isPlaying
                + ", hasPlayer=" + (mediaPlayer != null));
        if (mediaPlayer != null && !isPlaying) {
            // Audio Focus erneut anfordern
            int result = audioManager.requestAudioFocus(audioFocusRequest);
            if (result != AudioManager.AUDIOFOCUS_REQUEST_GRANTED) {
                Log.w(TAG, "Audio Focus nicht erhalten in resumePlayback()");
                return;
            }
            // Lautstärke wiederherstellen – nach Fade-out ist sie nahe 0
            mediaPlayer.setVolume(effectiveVolume(currentVolume), effectiveVolume(currentVolume));
            try {
                mediaPlayer.start();
            } catch (IllegalStateException e) {
                Log.e(TAG, "IllegalStateException in resumePlayback()", e);
                return;
            }
            isPlaying = true;
            updatePlaybackState(PlaybackStateCompat.STATE_PLAYING);
            showNotification();

            // Sektions-Gain-Handler neu starten falls Sektionsdaten vorhanden
            if (currentSectionalGains != null) {
                mainHandler.removeCallbacks(sectionalGainRunnable);
                mainHandler.postDelayed(sectionalGainRunnable, SECTIONAL_GAIN_INTERVAL_MS);
            }

            if (callback != null) {
                callback.onPlaybackStateChanged(true);
            }
        }
    }

    /**
     * Stoppt die Wiedergabe vollständig und beendet den Service.
     */
    public void stopPlayback() {
        Log.d(TAG, "stopPlayback()");
        stopTimerInternal();
        releaseMediaPlayer();
        isPlaying = false;
        currentTrack = null;
        abandonAudioFocus();
        releaseServiceWakeLock();

        updatePlaybackState(PlaybackStateCompat.STATE_STOPPED);

        if (callback != null) {
            callback.onPlaybackStateChanged(false);
            callback.onTimerFinished();
        }

        stopForeground(STOP_FOREGROUND_REMOVE);
        stopSelf();
    }

    /**
     * Springt zum nächsten zufälligen Track.
     */
    public void skipToNext() {
        Log.d(TAG, "skipToNext()");
        startRandomPlayback();
    }

    // ===== Meditation =====

    /**
     * Schaltet die 4-7-8 Atemübung ein oder aus.
     * Beim Einschalten wird die Musikwiedergabe pausiert.
     * Beim Ausschalten kehrt der Service in den normalen Schlafmodus zurück.
     */
    public void toggleMeditation() {
        if (meditationController != null && meditationController.isRunning()) {
            stopMeditation();
        } else {
            startMeditation();
        }
    }

    /** Startet die Atemübung (pausiert laufende Wiedergabe). */
    public void startMeditation() {
        Log.d(TAG, "startMeditation()");

        // Sleep-Timer stoppen – darf während Meditation nicht die Notification überschreiben
        stopTimerInternal();

        // Musik anhalten und Audio-Focus freigeben, damit Meditations-Töne ungestört spielen
        if (isPlaying) {
            pausePlayback();
        }
        abandonAudioFocus();

        // Lautstärke: mindestens 30%, damit die Töne deutlich hörbar sind
        float vol = Math.max(0.30f, currentVolume);
        meditationController.start(vol);

        // Notification aktualisieren
        showMeditationNotification();
    }

    /** Stoppt die Atemübung. */
    public void stopMeditation() {
        Log.d(TAG, "stopMeditation()");
        meditationController.stop();
        if (callback != null) {
            callback.onMeditationStateChanged(false,
                    MeditationController.Phase.FINISHED, 0);
        }
        // Schlafmodus-Notification wiederherstellen
        showSleepModeNotification();
    }

    /** Gibt zurück ob die Atemübung gerade läuft. */
    public boolean isMeditating() {
        return meditationController != null && meditationController.isRunning();
    }

    /**
     * Setzt die Lautstärke (0.0 bis 1.0).
     * Wird der Wert manuell geändert, wird ein laufender Fade-out abgebrochen.
     */
    public void setVolume(float volume) {
        currentVolume = Math.max(0.0f, Math.min(1.0f, volume));
        // Manueller Eingriff bricht den Fade-out ab
        if (isFadingOut) {
            isFadingOut = false;
            Log.d(TAG, "Fade-out abgebrochen durch manuellen Lautstärke-Eingriff");
        }
        if (mediaPlayer != null) {
            mediaPlayer.setVolume(effectiveVolume(currentVolume), effectiveVolume(currentVolume));
        }
    }

    /**
     * Setzt die Timer-Dauer und startet den Timer.
     * Gibt beim Start die aktuelle Uhrzeit per Sprachsynthese aus.
     */
    public void startTimer(int minutes) {
        timerTotalMinutes = minutes;
        prefsManager.saveTimerMinutes(minutes);

        stopTimerInternal();

        long millis = minutes * 60L * 1000L;
        timerMillisRemaining = millis;
        isTimerRunning = true;
        isFadingOut = false; // Fade-out-Zustand zurücksetzen

        Log.d(TAG, "Timer gestartet: " + minutes + " Minuten");


        sleepTimer = new CountDownTimer(millis, 1000) {
            @Override
            public void onTick(long millisUntilFinished) {
                timerMillisRemaining = millisUntilFinished;

                // === Fade-out Logik ===
                if (!isFadingOut && millisUntilFinished <= FADE_OUT_DURATION_MS) {
                    // Fade-out beginnt: Lautstärke für nächsten Start speichern
                    isFadingOut = true;
                    volumeBeforeFade = currentVolume;
                    prefsManager.saveVolume(VolumeHelper.volumeToProgress(currentVolume));
                    Log.d(TAG, "Fade-out gestartet. Lautstärke gespeichert: " + currentVolume);
                }
                if (isFadingOut && volumeBeforeFade > 0f) {
                    float fadeFactor = (float) millisUntilFinished / FADE_OUT_DURATION_MS;
                    float fadedVolume = effectiveVolume(volumeBeforeFade * fadeFactor);
                    if (mediaPlayer != null) {
                        mediaPlayer.setVolume(fadedVolume, fadedVolume);
                    }
                }

                if (callback != null) {
                    callback.onTimerTick(millisUntilFinished);
                }
            }

            @Override
            public void onFinish() {
                isTimerRunning = false;
                timerMillisRemaining = 0;
                isFadingOut = false;
                Log.d(TAG, "Sleep-Timer abgelaufen – pausiere Wiedergabe");

                // Lautstärke wiederherstellen BEVOR pausiert wird,
                // damit beim nächsten Resume nicht der Fade-out-Wert (~0) im Player steckt
                if (mediaPlayer != null) {
                    mediaPlayer.setVolume(effectiveVolume(currentVolume), effectiveVolume(currentVolume));
                }

                // Wiedergabe pausieren (nicht komplett stoppen)
                pausePlayback();

                if (callback != null) {
                    callback.onTimerFinished();
                }

                // *** KRITISCH: Foreground-Status BEIBEHALTEN ***
                // Statt stopForeground() zeigen wir eine spezielle "Schlafmodus"-Notification.
                // Nur so bleibt der Service als Foreground-Service am Leben und die
                // MediaSession empfängt weiterhin Kopfhörer-Tasten-Events – auch nach
                // langer Pause (z.B. nachts beim Wiedereinschlafen).
                // Der Nutzer kann die Notification wegwischen um den Service zu beenden.
                showSleepModeNotification();

                Log.d(TAG, "Service bleibt im Foreground (Sleep-Mode-Notification). "
                        + "Kopfhörertaste kann Wiedergabe jederzeit neu starten.");
            }
        };
        sleepTimer.start();
    }

    /**
     * Startet den Timer mit der aktuellen Dauer neu.
     */
    public void restartTimer() {
        startTimer(timerTotalMinutes);
    }

    // ===== Getter =====

    public boolean isPlaying() {
        return isPlaying;
    }

    public boolean isRandomMode() {
        return isRandomMode;
    }

    /**
     * Setzt den Wiedergabe-Modus.
     * @param random true = zufällig, false = in Listenreihenfolge
     */
    public void setRandomMode(boolean random) {
        this.isRandomMode = random;
        prefsManager.saveRandomMode(random);
        Log.d(TAG, "Wiedergabe-Modus: " + (random ? "Zufall" : "Reihenfolge"));
    }

    public TrackSelector.TrackInfo getCurrentTrack() {
        return currentTrack;
    }

    /** Aktuelle Wiedergabeposition in Millisekunden (0 wenn kein Track). */
    public int getCurrentPosition() {
        if (mediaPlayer != null) {
            try {
                return mediaPlayer.getCurrentPosition();
            } catch (IllegalStateException e) {
                return 0;
            }
        }
        return 0;
    }

    /** Gesamtdauer des aktuellen Tracks in Millisekunden (0 wenn kein Track). */
    public int getDuration() {
        if (mediaPlayer != null) {
            try {
                int d = mediaPlayer.getDuration();
                return d > 0 ? d : 0;
            } catch (IllegalStateException e) {
                return 0;
            }
        }
        return 0;
    }

    /** Springt zur angegebenen Position in Millisekunden. */
    public void seekTo(int positionMs) {
        if (mediaPlayer != null) {
            try {
                mediaPlayer.seekTo(positionMs);
                Log.d(TAG, "seekTo: " + positionMs + "ms");
            } catch (IllegalStateException e) {
                Log.w(TAG, "seekTo: IllegalStateException", e);
            }
        }
    }

    public long getTimerMillisRemaining() {
        return timerMillisRemaining;
    }

    public boolean isTimerRunning() {
        return isTimerRunning;
    }

    public int getTimerTotalMinutes() {
        return timerTotalMinutes;
    }

    public TrackSelector getTrackSelector() {
        return trackSelector;
    }

    public MediaSessionCompat getMediaSession() {
        return mediaSession;
    }

    // ===== Private Hilfsmethoden =====

    private void releaseMediaPlayer() {
        mainHandler.removeCallbacks(sectionalGainRunnable);
        if (mediaPlayer != null) {
            Log.d(TAG, "releaseMediaPlayer()");
            try {
                if (mediaPlayer.isPlaying()) {
                    mediaPlayer.stop();
                }
            } catch (IllegalStateException e) {
                Log.w(TAG, "IllegalStateException beim Stoppen des MediaPlayers", e);
            }
            try {
                mediaPlayer.release();
            } catch (Exception e) {
                Log.w(TAG, "Fehler beim Release des MediaPlayers", e);
            }
            mediaPlayer = null;
        }
    }

    private void stopTimerInternal() {
        if (sleepTimer != null) {
            sleepTimer.cancel();
            sleepTimer = null;
        }
        // Falls ein Fade-out lief, Lautstärke wiederherstellen
        if (isFadingOut && mediaPlayer != null) {
            mediaPlayer.setVolume(effectiveVolume(currentVolume), effectiveVolume(currentVolume));
        }
        isFadingOut = false;
        isTimerRunning = false;
    }

    private void abandonAudioFocus() {
        if (audioFocusRequest != null) {
            audioManager.abandonAudioFocusRequest(audioFocusRequest);
        }
    }

    private void onAudioFocusChange(int focusChange) {
        Log.d(TAG, "onAudioFocusChange: " + focusChange);
        switch (focusChange) {
            case AudioManager.AUDIOFOCUS_LOSS:
                // Dauerhafter Verlust → pausieren
                pausePlayback();
                break;
            case AudioManager.AUDIOFOCUS_LOSS_TRANSIENT:
                // Kurzer Verlust → pausieren
                pausePlayback();
                break;
            case AudioManager.AUDIOFOCUS_LOSS_TRANSIENT_CAN_DUCK:
                // Leiser machen
                if (mediaPlayer != null) {
                    mediaPlayer.setVolume(effectiveVolume(currentVolume) * 0.3f,
                            effectiveVolume(currentVolume) * 0.3f);
                }
                break;
            case AudioManager.AUDIOFOCUS_GAIN:
                // Focus zurück → Lautstärke wiederherstellen
                if (mediaPlayer != null) {
                    mediaPlayer.setVolume(effectiveVolume(currentVolume), effectiveVolume(currentVolume));
                }
                // Nicht automatisch fortsetzen – Nutzer schläft vielleicht
                break;
        }
    }

    private void updatePlaybackState(int state) {
        if (mediaSession == null) return;

        long position = 0;
        if (mediaPlayer != null) {
            try {
                position = mediaPlayer.getCurrentPosition();
            } catch (IllegalStateException e) {
                // Ignore
            }
        }

        PlaybackStateCompat.Builder builder = new PlaybackStateCompat.Builder()
                .setActions(
                        PlaybackStateCompat.ACTION_PLAY
                                | PlaybackStateCompat.ACTION_PAUSE
                                | PlaybackStateCompat.ACTION_PLAY_PAUSE
                                | PlaybackStateCompat.ACTION_STOP
                                | PlaybackStateCompat.ACTION_SKIP_TO_NEXT)
                .setState(state, position, 1.0f);

        mediaSession.setPlaybackState(builder.build());
    }

    private void updateMediaMetadata(TrackSelector.TrackInfo track) {
        if (mediaSession == null || track == null) return;

        MediaMetadataCompat metadata = new MediaMetadataCompat.Builder()
                .putString(MediaMetadataCompat.METADATA_KEY_TITLE, track.title)
                .putString(MediaMetadataCompat.METADATA_KEY_ARTIST, track.artist)
                .putString(MediaMetadataCompat.METADATA_KEY_ALBUM, track.album)
                .putLong(MediaMetadataCompat.METADATA_KEY_DURATION, track.duration)
                .build();

        mediaSession.setMetadata(metadata);
    }

    private void showNotification() {
        String title = currentTrack != null ? currentTrack.title : "SleepPlayer";
        Notification notification = NotificationHelper.buildNotification(
                this, mediaSession, title, isPlaying);
        startForeground(NotificationHelper.NOTIFICATION_ID, notification);
    }

    /**
     * Zeigt die "Schlafmodus"-Notification und hält den Service im Foreground.     * Wird aufgerufen wenn der Sleep-Timer abläuft und Wiedergabe pausiert wurde.
     * Hält die MediaSession aktiv → Kopfhörer-Tasten weiterhin nutzbar.
     */
    private void showSleepModeNotification() {
        String title = currentTrack != null ? currentTrack.title : "SleepPlayer";
        Notification notification = NotificationHelper.buildSleepNotification(
                this, mediaSession, title);
        // startForeground() hält den Service als Foreground-Service am Leben
        startForeground(NotificationHelper.NOTIFICATION_ID, notification);
        Log.d(TAG, "Sleep-Mode-Notification aktiv – Service bleibt im Foreground");
    }

    /**
     * Zeigt die Meditations-Notification und hält den Service im Foreground.
     */
    private void showMeditationNotification() {
        Notification notification = NotificationHelper.buildMeditationNotification(
                this, mediaSession,
                "Einatmen 4s · Halten 7s · Ausatmen 8s · Doppelklick = Ende");
        startForeground(NotificationHelper.NOTIFICATION_ID, notification);
        Log.d(TAG, "Meditations-Notification aktiv");
    }

    /** Acquiriert den Service-WakeLock (idempotent). */
    private void acquireServiceWakeLock() {        if (serviceWakeLock != null && !serviceWakeLock.isHeld()) {
            serviceWakeLock.acquire();
            Log.d(TAG, "Service-WakeLock acquired");
        }
    }

    /** Gibt den Service-WakeLock frei (idempotent). */
    private void releaseServiceWakeLock() {
        if (serviceWakeLock != null && serviceWakeLock.isHeld()) {
            serviceWakeLock.release();
            Log.d(TAG, "Service-WakeLock released");
        }
    }

    /**
     * Berechnet die effektive Lautstärke unter Berücksichtigung des Track-Gains.
     * Ergebnis ist immer im Bereich [0.0, 1.0].
     */
    private float effectiveVolume(float base) {
        return Math.max(0.0f, Math.min(1.0f, base * currentTrackGain));
    }

    /**
     * Liest die aktuelle Sektions-Gain und wendet sie auf den MediaPlayer an.
     * Wird periodisch durch sectionalGainRunnable aufgerufen.
     */
    private void applySectionalGain() {
        if (currentSectionalGains == null || mediaPlayer == null || !isPlaying) return;
        try {
            int posMs = mediaPlayer.getCurrentPosition();
            float sectionGain = findSectionGain(posMs);
            float vol = Math.max(0f, Math.min(1f, currentVolume * sectionGain));
            mediaPlayer.setVolume(vol, vol);
            Log.d(TAG, "Sektions-Gain bei " + posMs + "ms: " + sectionGain + "×");
        } catch (IllegalStateException e) {
            Log.w(TAG, "applySectionalGain: IllegalStateException", e);
        }
    }

    /**
     * Findet den passenden Sektions-Gain-Multiplier für eine gegebene Position.
     * Die Sektionen sind nach Startzeit sortiert gespeichert.
     */
    private float findSectionGain(int positionMs) {
        if (currentSectionalGains == null || currentSectionalGains.isEmpty()) return currentTrackGain;
        float gain = currentSectionalGains.get(0)[1];
        for (float[] section : currentSectionalGains) {
            if (section[0] <= positionMs) {
                gain = section[1];
            } else {
                break;
            }
        }
        return gain;
    }

    /** Gibt den NormalizationStore zurück (für die Activity). */
    public NormalizationStore getNormalizationStore() {
        return normalizationStore;
    }
}

package com.example.sleepplayer;

import android.app.Notification;
import android.app.Service;
import android.content.Intent;
import android.media.AudioAttributes;
import android.media.AudioFocusRequest;
import android.media.AudioManager;
import android.media.MediaPlayer;
import android.os.Binder;
import android.os.CountDownTimer;
import android.os.Handler;
import android.os.IBinder;
import android.os.Looper;
import android.os.PowerManager;
import android.support.v4.media.MediaMetadataCompat;
import android.support.v4.media.session.MediaSessionCompat;
import android.support.v4.media.session.PlaybackStateCompat;
import android.util.Log;

import androidx.annotation.Nullable;
import androidx.media.session.MediaButtonReceiver;

import java.io.IOException;
import java.util.List;
import java.util.concurrent.ExecutorService;import java.util.concurrent.Executors;

/**
 * Foreground-Service für die Audio-Wiedergabe.
 *
 * Verantwortlich für:
 * - MediaPlayer Verwaltung
 * - MediaSession (Kopfhörer-Tasten)
 * - Sleep-Timer (CountDownTimer)
 * - Audio Focus
 * - WakeLock
 * - Foreground Notification
 */
public class PlaybackService extends Service {

    private static final String TAG = "PlaybackService";

    /** Dauer des Fade-outs in Millisekunden (letzte 60 Sekunden vor Timer-Ende). */
    private static final long FADE_OUT_DURATION_MS = 60_000L;

    // Binder für Activity-Kommunikation
    private final IBinder binder = new LocalBinder();

    /** Hintergrund-Thread für MediaStore-Abfragen (verhindert Main-Thread I/O / ANR). */
    private final ExecutorService ioExecutor = Executors.newSingleThreadExecutor();
    /** Handler zum Zurückwechseln auf den Main-Thread nach I/O. */
    private final Handler mainHandler = new Handler(Looper.getMainLooper());

    private MediaPlayer mediaPlayer;
    private MediaSessionCompat mediaSession;
    private AudioManager audioManager;
    private AudioFocusRequest audioFocusRequest;
    private TrackSelector trackSelector;
    private PrefsManager prefsManager;

    private CountDownTimer sleepTimer;
    private long timerMillisRemaining = 0;
    private int timerTotalMinutes = 30;
    private boolean isTimerRunning = false;

    private float currentVolume = 0.15f;
    private boolean isPlaying = false;
    private boolean isRandomMode = true;

    /**
     * Generations-Zähler zur Vermeidung von Race-Conditions beim asynchronen Track-Laden.
     *
     * Problem ohne diesen Zähler:
     *   1. Track A läuft zu Ende → onCompletion → startRandomPlayback() startet IO-Thread
     *   2. Nutzer wählt währenddessen Track B aus → playTrackInternal(B) läuft sofort
     *   3. IO-Thread fertig → mainHandler.post(playTrackInternal(random)) → überschreibt B!
     *
     * Lösung: playTrackInternal() inkrementiert den Zähler. Der async-Callback prüft
     * ob der Zähler noch passt; falls nicht, wird der veraltete Aufruf verworfen.
     */
    private int playbackGeneration = 0;

    // Fade-out Zustand
    private boolean isFadingOut = false;
    private float volumeBeforeFade = 0f;

    /**
     * Normalisierungs-Gain des aktuell spielenden Tracks (1.0 = keine Änderung).
     * Wird in playTrackInternal() gesetzt.
     */
    private float currentTrackGain = 1.0f;

    /**
     * Sektionsweise Gain-Daten für den aktuellen Track.
     * float[2] = [sectionStartMs, gainMultiplier]. null = keine Sektionsdaten.
     */
    private List<float[]> currentSectionalGains = null;

    /** Handler-Runnable zum periodischen Anpassen des Sektions-Gains. */
    private static final int SECTIONAL_GAIN_INTERVAL_MS = 2000;
    private final Runnable sectionalGainRunnable = new Runnable() {
        @Override
        public void run() {
            applySectionalGain();
            if (isPlaying && currentSectionalGains != null) {
                mainHandler.postDelayed(this, SECTIONAL_GAIN_INTERVAL_MS);
            }
        }
    };

    /** Normalisierungs-Daten (Referenz-Track + Gain-Offsets). */
    private NormalizationStore normalizationStore;

    /**
     * WakeLock auf Service-Ebene – hält die CPU wach, damit der Service im
     * Hintergrund nicht vom System in einen Zustand versetzt wird, in dem er
     * keine Intents mehr empfangen kann.
     *
     * PARTIAL_WAKE_LOCK: CPU läuft, Bildschirm darf aus → batterieschonend.
     * Wird bei echter Wiedergabe und im Schlafmodus (Timer abgelaufen, aber Service
     * noch aktiv) gehalten; wird nur in stopPlayback() / onDestroy() freigegeben.
     */
    private PowerManager.WakeLock serviceWakeLock;

    private TrackSelector.TrackInfo currentTrack;

    /** Sprachsynthese für Zeitansage beim Timer-Start. */
    private TtsHelper ttsHelper;

    /** Steuerung der 4-7-8 Atemübung. */
    private MeditationController meditationController;

    // Callback-Interface für UI-Updates
    private PlaybackCallback callback;

    public interface PlaybackCallback {
        void onTrackChanged(TrackSelector.TrackInfo track);
        void onPlaybackStateChanged(boolean isPlaying);
        void onTimerTick(long millisRemaining);
        void onTimerFinished();
        /** Wird aufgerufen wenn der Meditations-Modus ein-/ausgeschaltet wird. */
        default void onMeditationStateChanged(boolean active, MeditationController.Phase phase, int cycle) {}
    }

    public class LocalBinder extends Binder {
        public PlaybackService getService() {
            return PlaybackService.this;
        }
    }

    @Override
    public void onCreate() {
        super.onCreate();
        Log.d(TAG, "Service created (instance=" + System.identityHashCode(this) + ")");

        prefsManager = new PrefsManager(this);
        trackSelector = new TrackSelector(this);
        audioManager = (AudioManager) getSystemService(AUDIO_SERVICE);
        normalizationStore = new NormalizationStore(this);

        // Meditations-Controller initialisieren
        meditationController = new MeditationController(this, new MeditationController.MeditationCallback() {
            @Override
            public void onPhaseChanged(MeditationController.Phase phase, int cycle) {
                Log.d(TAG, "Meditation Phase: " + phase + " Zyklus " + cycle);
                if (callback != null) {
                    callback.onMeditationStateChanged(true, phase, cycle);
                }
            }
            @Override
            public void onMeditationFinished() {
                Log.d(TAG, "Meditation beendet");
                if (callback != null) {
                    callback.onMeditationStateChanged(false,
                            MeditationController.Phase.FINISHED, 0);
                }
                // Automatisch zurück in den normalen Schlafmodus wechseln
                showSleepModeNotification();
            }
        });

        // Notification Channel erstellen
        NotificationHelper.createChannel(this);

        // Service-WakeLock initialisieren (noch nicht acquiren)
        PowerManager pm = (PowerManager) getSystemService(POWER_SERVICE);
        serviceWakeLock = pm.newWakeLock(
                PowerManager.PARTIAL_WAKE_LOCK, "SleepPlayer:ServiceWakeLock");
        serviceWakeLock.setReferenceCounted(false);

        // MediaSession erstellen (MUSS vor startForeground() stehen!)
        mediaSession = new MediaSessionCompat(this, "SleepPlayer");
        mediaSession.setCallback(new MediaSessionCallback(this));
        mediaSession.setFlags(
                MediaSessionCompat.FLAG_HANDLES_MEDIA_BUTTONS
                        | MediaSessionCompat.FLAG_HANDLES_TRANSPORT_CONTROLS);
        mediaSession.setActive(true);

        // Initialen PlaybackState setzen – ohne diesen ignoriert Android
        // die MediaSession beim allerersten Kopfhörer-Tastendruck
        updatePlaybackState(PlaybackStateCompat.STATE_STOPPED);

        // Sofort als Foreground-Service starten – stellt sicher dass die MediaSession
        // von Anfang an Kopfhörer-Tasten empfängt, auch beim allerersten App-Start
        // ohne vorherigen Track. Der Service bleibt so immer erreichbar.
        // WICHTIG: erst NACH mediaSession-Initialisierung aufrufen!
        Notification initialNotification = NotificationHelper.buildNotification(
                this, mediaSession, getString(R.string.app_name), false);
        startForeground(NotificationHelper.NOTIFICATION_ID, initialNotification);

        // Audio Focus Request
        AudioAttributes audioAttributes = new AudioAttributes.Builder()
                .setUsage(AudioAttributes.USAGE_MEDIA)
                .setContentType(AudioAttributes.CONTENT_TYPE_MUSIC)
                .build();

        audioFocusRequest = new AudioFocusRequest.Builder(AudioManager.AUDIOFOCUS_GAIN)
                .setAudioAttributes(audioAttributes)
                .setOnAudioFocusChangeListener(this::onAudioFocusChange)
                .build();

        // Gespeicherte Lautstärke laden
        int savedProgress = prefsManager.getVolume();
        currentVolume = VolumeHelper.progressToVolume(savedProgress);

        // Gespeicherten Wiedergabe-Modus laden
        isRandomMode = prefsManager.isRandomMode();

        // Gespeicherte Timer-Dauer laden
        timerTotalMinutes = prefsManager.getTimerMinutes();

        // TTS initialisieren (asynchron – bereit bevor der erste Timer gestartet wird)
        ttsHelper = new TtsHelper(this);

        // Track-Liste im Hintergrund vorladen, damit beim ersten Abspielen
        // KEIN MediaStore-Query auf dem Main-Thread nötig ist (ANR-Prävention).
        ioExecutor.execute(() -> {
            List<TrackSelector.TrackInfo> tracks = trackSelector.getAllTracks();
            Log.d(TAG, "Track-Cache vorgeladen: " + tracks.size() + " Titel");
        });
    }

    @Override
    public int onStartCommand(Intent intent, int flags, int startId) {
        if (intent != null) {
            String action = intent.getAction();

            if (NotificationHelper.ACTION_PLAY_PAUSE.equals(action)) {
                togglePlayPause();
            } else if (NotificationHelper.ACTION_STOP.equals(action)) {
                stopPlayback();
            } else if (NotificationHelper.ACTION_DISMISS.equals(action)) {
                // Nutzer hat die Sleep-Mode-Notification weggewischt → Service vollständig beenden
                Log.d(TAG, "ACTION_DISMISS empfangen – Service wird beendet");
                stopPlayback();
            } else {
                // Könnte ein MediaButton-Intent sein
                MediaButtonReceiver.handleIntent(mediaSession, intent);
            }
        }

        return START_STICKY;
    }

    @Nullable
    @Override
    public IBinder onBind(Intent intent) {
        return binder;
    }

    @Override
    public void onDestroy() {
        Log.d(TAG, "Service destroyed (instance=" + System.identityHashCode(this) + ")");
        ioExecutor.shutdownNow();
        stopTimerInternal();
        releaseMediaPlayer();
        if (ttsHelper != null) {
            ttsHelper.release();
            ttsHelper = null;
        }
        if (meditationController != null) {
            meditationController.release();
            meditationController = null;
        }
        if (mediaSession != null) {
            mediaSession.setActive(false);
            mediaSession.release();
        }
        abandonAudioFocus();
        releaseServiceWakeLock();
        super.onDestroy();
    }

    // ===== Öffentliche Methoden für Activity und MediaSessionCallback =====

    public void setCallback(PlaybackCallback callback) {
        this.callback = callback;
    }

    /**
     * Spielt den nächsten Titel ab – zufällig oder aktuellen wiederholen,
     * je nach aktuellem Modus.
     *
     * WICHTIG: Die MediaStore-Abfrage läuft auf einem Hintergrund-Thread,
     * um ANR auf dem Main-Thread zu verhindern.
     */
    public void startRandomPlayback() {
        Log.d(TAG, "startRandomPlayback() – isRandomMode=" + isRandomMode
                + ", currentTrack=" + (currentTrack != null ? currentTrack.title : "null"));
        if (isRandomMode) {
            // Generation zum Zeitpunkt dieses Aufrufs merken
            final int generation = playbackGeneration;
            ioExecutor.execute(() -> {
                TrackSelector.TrackInfo track = trackSelector.getNextTrack();
                Log.d(TAG, "Nächster Track ausgewählt: "
                        + (track != null ? track.title : "keiner!"));
                mainHandler.post(() -> {
                    // Nur abspielen wenn kein direkter Track-Wechsel dazwischengekommen ist
                    if (generation != playbackGeneration) {
                        Log.d(TAG, "startRandomPlayback: Generation veraltet – abgebrochen "
                                + "(war=" + generation + ", aktuell=" + playbackGeneration + ")");
                        return;
                    }
                    if (track != null) {
                        playTrackInternal(track);
                    } else {
                        Log.w(TAG, "Keine Tracks verfügbar – Wiedergabe gestoppt");
                    }
                });
            });
        } else {
            repeatCurrentTrack();
        }
    }

    /**
     * Wiederholt den aktuellen Track (Einzeltitel-Wiederholung).
     * Falls noch kein Track gespielt wurde, startet einen zufälligen.
     */
    private void repeatCurrentTrack() {
        if (currentTrack != null) {
            Log.d(TAG, "repeatCurrentTrack: " + currentTrack.title);
            playTrackInternal(currentTrack);
        } else {
            Log.d(TAG, "repeatCurrentTrack: kein aktueller Track – lade zufällig");
            final int generation = playbackGeneration;
            ioExecutor.execute(() -> {
                TrackSelector.TrackInfo track = trackSelector.getNextTrack();
                mainHandler.post(() -> {
                    if (generation != playbackGeneration) {
                        Log.d(TAG, "repeatCurrentTrack: Generation veraltet – abgebrochen");
                        return;
                    }
                    if (track != null) {
                        playTrackInternal(track);
                    }
                });
            });
        }
    }

    /**
     * Spielt einen bestimmten Track ab (z.B. direkte Selektion aus der Liste).
     * Wenn der Player gerade nicht läuft (neuer Start), wird zuerst die Uhrzeit angesagt.
     * Wenn bereits ein Track läuft (Wechsel), startet der neue Track sofort ohne Ansage.
     */
    public void playTrack(TrackSelector.TrackInfo track) {
        if (!isPlaying) {
            speakTimeAndThen(() -> playTrackInternal(track));
        } else {
            playTrackInternal(track);
        }
    }

    /**
     * Interne Wiedergabe-Implementierung.
     *
     * Verwendet eine lokale 'player'-Variable anstelle von 'mediaPlayer',
     * um veraltete Callbacks (von einem bereits ersetzten MediaPlayer) sicher
     * zu erkennen und zu ignorieren.
     */
    private void playTrackInternal(TrackSelector.TrackInfo track) {
        if (track == null) {
            Log.w(TAG, "playTrackInternal: track ist null, abgebrochen");
            return;
        }
        // Generation inkrementieren → macht alle laufenden async-Anfragen ungültig
        playbackGeneration++;
        Log.d(TAG, "playTrackInternal: " + track.title + " / " + track.artist
                + " (generation=" + playbackGeneration + ")");

        // Audio Focus anfordern
        int result = audioManager.requestAudioFocus(audioFocusRequest);
        if (result != AudioManager.AUDIOFOCUS_REQUEST_GRANTED) {
            Log.w(TAG, "Audio Focus nicht erhalten – Wiedergabe abgebrochen");
            return;
        }

        // Service-WakeLock halten – verhindert, dass der Service vom System
        // "eingeschläfert" wird und keine Intents mehr empfangen kann
        acquireServiceWakeLock();

        // Alten Player stoppen und freigeben
        releaseMediaPlayer();

        // Normalisierungs-Gain für diesen Track laden
        currentTrackGain = normalizationStore.getGain(track.uri.toString());
        // Sektionsweise Gains laden (null wenn nicht vorhanden)
        currentSectionalGains = normalizationStore.getSectionalGains(track.uri.toString());
        mainHandler.removeCallbacks(sectionalGainRunnable);
        Log.d(TAG, "Track-Gain: " + currentTrackGain + "× für " + track.title
                + (currentSectionalGains != null ? " (" + currentSectionalGains.size() + " Sektionen)" : ""));

        try {
            MediaPlayer player = new MediaPlayer();
            mediaPlayer = player; // sofort setzen, damit Stale-Check funktioniert

            player.setAudioAttributes(
                    new AudioAttributes.Builder()
                            .setUsage(AudioAttributes.USAGE_MEDIA)
                            .setContentType(AudioAttributes.CONTENT_TYPE_MUSIC)
                            .build());
            player.setDataSource(this, track.uri);
            player.setWakeMode(this, PowerManager.PARTIAL_WAKE_LOCK);
            player.setVolume(effectiveVolume(currentVolume), effectiveVolume(currentVolume));

            player.setOnPreparedListener(mp -> {
                // Sicherheitscheck: Wurde dieser Player inzwischen ersetzt?
                if (mediaPlayer != player) {
                    Log.w(TAG, "onPrepared: Player wurde bereits ersetzt, ignoriere");
                    return;
                }
                Log.d(TAG, "onPrepared: starte '" + track.title + "'");
                mp.start();
                isPlaying = true;
                currentTrack = track;

                updatePlaybackState(PlaybackStateCompat.STATE_PLAYING);
                updateMediaMetadata(track);
                showNotification();

                if (callback != null) {
                    callback.onTrackChanged(track);
                    callback.onPlaybackStateChanged(true);
                }

                // Sektions-Gain-Handler starten falls Sektionsdaten vorhanden
                if (currentSectionalGains != null) {
                    mainHandler.postDelayed(sectionalGainRunnable, SECTIONAL_GAIN_INTERVAL_MS);
                }

                // Timer starten falls noch nicht läuft
                if (!isTimerRunning) {
                    Log.d(TAG, "Timer noch nicht aktiv – starte Timer");
                    startTimer(timerTotalMinutes);
                }
            });

            player.setOnCompletionListener(mp -> {
                // Sicherheitscheck: Wurde dieser Player inzwischen ersetzt?
                if (mediaPlayer != player) {
                    Log.w(TAG, "onCompletion: Player wurde bereits ersetzt, ignoriere");
                    return;
                }
                Log.d(TAG, "onCompletion: '" + track.title + "' fertig – nächster Track");
                startRandomPlayback();
            });

            player.setOnErrorListener((mp, what, extra) -> {
                Log.e(TAG, "MediaPlayer Fehler: what=" + what + " extra=" + extra
                        + " track='" + track.title + "'");
                if (mediaPlayer != player) {
                    Log.w(TAG, "onError: Player wurde bereits ersetzt, ignoriere");
                    return true;
                }
                // Bei Fehler: nächsten Track versuchen
                startRandomPlayback();
                return true;
            });

            Log.d(TAG, "prepareAsync() gestartet für: " + track.title);
            player.prepareAsync();

        } catch (IOException e) {
            Log.e(TAG, "IOException beim Laden: " + track.title, e);
            // Nächsten Track versuchen
            startRandomPlayback();
        } catch (Exception e) {
            Log.e(TAG, "Unerwarteter Fehler in playTrackInternal", e);
        }
    }

    /**
     * Toggle Play/Pause – wird von der Kopfhörer-Taste aufgerufen.
     * Spricht zuerst die aktuelle Uhrzeit an (passend zur Track-Lautstärke),
     * startet danach den Track bzw. setzt die Wiedergabe fort.
     */
    public void togglePlayPause() {
        Log.d(TAG, "togglePlayPause() – isPlaying=" + isPlaying
                + ", hasPlayer=" + (mediaPlayer != null)
                + ", currentTrack=" + (currentTrack != null ? currentTrack.title : "null"));

        // Wenn Meditation läuft → Pause = Meditation beenden, zurück in Schlafmodus
        if (isMeditating()) {
            Log.d(TAG, "togglePlayPause: Meditation läuft → stoppe Meditation");
            stopMeditation();
            return;
        }

        if (isPlaying) {
            pausePlayback();
        } else {
            if (mediaPlayer == null || currentTrack == null) {
                // Neuer Start: TTS → dann Track laden
                speakTimeAndThen(() -> {
                    startRandomPlayback();
                    // Timer startet in onPrepared falls noch nicht aktiv;
                    // hier sicherheitshalber auch direkt (doppelt-sicher):
                    if (!isTimerRunning) restartTimer();
                });
            } else {
                // Fortsetzen nach Pause: TTS → dann resume
                speakTimeAndThen(() -> {
                    resumePlayback();
                    restartTimer();
                });
            }
        }
    }

    /**
     * Spricht die aktuelle Uhrzeit (mit Track-Lautstärke) und ruft danach {@code action} aus.
     * Falls TTS deaktiviert oder nicht verfügbar, wird {@code action} sofort ausgeführt.
     */
    private void speakTimeAndThen(Runnable action) {
        if (ttsHelper != null && prefsManager.isTtsEnabled()) {
            ttsHelper.speakCurrentTime(currentVolume, action);
        } else {
            action.run();
        }
    }

    /**
     * Pausiert die Wiedergabe.
     */
    public void pausePlayback() {
        Log.d(TAG, "pausePlayback() – isPlaying=" + isPlaying);
        if (mediaPlayer != null && isPlaying) {
            try {
                mediaPlayer.pause();
            } catch (IllegalStateException e) {
                Log.e(TAG, "IllegalStateException in pausePlayback()", e);
                // Player in unerwartetem Zustand – freigeben
                releaseMediaPlayer();
            }
            isPlaying = false;
            updatePlaybackState(PlaybackStateCompat.STATE_PAUSED);
            showNotification();

            if (callback != null) {
                callback.onPlaybackStateChanged(false);
            }
        }
    }

    /**
     * Setzt die Wiedergabe fort.
     */
    public void resumePlayback() {
        Log.d(TAG, "resumePlayback() – isPlaying=" + isPlaying
                + ", hasPlayer=" + (mediaPlayer != null));
        if (mediaPlayer != null && !isPlaying) {
            // Audio Focus erneut anfordern
            int result = audioManager.requestAudioFocus(audioFocusRequest);
            if (result != AudioManager.AUDIOFOCUS_REQUEST_GRANTED) {
                Log.w(TAG, "Audio Focus nicht erhalten in resumePlayback()");
                return;
            }
            // Lautstärke wiederherstellen – nach Fade-out ist sie nahe 0
            mediaPlayer.setVolume(effectiveVolume(currentVolume), effectiveVolume(currentVolume));
            try {
                mediaPlayer.start();
            } catch (IllegalStateException e) {
                Log.e(TAG, "IllegalStateException in resumePlayback()", e);
                return;
            }
            isPlaying = true;
            updatePlaybackState(PlaybackStateCompat.STATE_PLAYING);
            showNotification();

            // Sektions-Gain-Handler neu starten falls Sektionsdaten vorhanden
            if (currentSectionalGains != null) {
                mainHandler.removeCallbacks(sectionalGainRunnable);
                mainHandler.postDelayed(sectionalGainRunnable, SECTIONAL_GAIN_INTERVAL_MS);
            }

            if (callback != null) {
                callback.onPlaybackStateChanged(true);
            }
        }
    }

    /**
     * Stoppt die Wiedergabe vollständig und beendet den Service.
     */
    public void stopPlayback() {
        Log.d(TAG, "stopPlayback()");
        stopTimerInternal();
        releaseMediaPlayer();
        isPlaying = false;
        currentTrack = null;
        abandonAudioFocus();
        releaseServiceWakeLock();

        updatePlaybackState(PlaybackStateCompat.STATE_STOPPED);

        if (callback != null) {
            callback.onPlaybackStateChanged(false);
            callback.onTimerFinished();
        }

        stopForeground(STOP_FOREGROUND_REMOVE);
        stopSelf();
    }

    /**
     * Springt zum nächsten zufälligen Track.
     */
    public void skipToNext() {
        Log.d(TAG, "skipToNext()");
        startRandomPlayback();
    }

    // ===== Meditation =====

    /**
     * Schaltet die 4-7-8 Atemübung ein oder aus.
     * Beim Einschalten wird die Musikwiedergabe pausiert.
     * Beim Ausschalten kehrt der Service in den normalen Schlafmodus zurück.
     */
    public void toggleMeditation() {
        if (meditationController != null && meditationController.isRunning()) {
            stopMeditation();
        } else {
            startMeditation();
        }
    }

    /** Startet die Atemübung (pausiert laufende Wiedergabe). */
    public void startMeditation() {
        Log.d(TAG, "startMeditation()");

        // Sleep-Timer stoppen – darf während Meditation nicht die Notification überschreiben
        stopTimerInternal();

        // Musik anhalten und Audio-Focus freigeben, damit Meditations-Töne ungestört spielen
        if (isPlaying) {
            pausePlayback();
        }
        abandonAudioFocus();

        // Lautstärke: mindestens 30%, damit die Töne deutlich hörbar sind
        float vol = Math.max(0.30f, currentVolume);
        meditationController.start(vol);

        // Notification aktualisieren
        showMeditationNotification();
    }

    /** Stoppt die Atemübung. */
    public void stopMeditation() {
        Log.d(TAG, "stopMeditation()");
        meditationController.stop();
        if (callback != null) {
            callback.onMeditationStateChanged(false,
                    MeditationController.Phase.FINISHED, 0);
        }
        // Schlafmodus-Notification wiederherstellen
        showSleepModeNotification();
    }

    /** Gibt zurück ob die Atemübung gerade läuft. */
    public boolean isMeditating() {
        return meditationController != null && meditationController.isRunning();
    }

    /**
     * Setzt die Lautstärke (0.0 bis 1.0).
     * Wird der Wert manuell geändert, wird ein laufender Fade-out abgebrochen.
     */
    public void setVolume(float volume) {
        currentVolume = Math.max(0.0f, Math.min(1.0f, volume));
        // Manueller Eingriff bricht den Fade-out ab
        if (isFadingOut) {
            isFadingOut = false;
            Log.d(TAG, "Fade-out abgebrochen durch manuellen Lautstärke-Eingriff");
        }
        if (mediaPlayer != null) {
            mediaPlayer.setVolume(effectiveVolume(currentVolume), effectiveVolume(currentVolume));
        }
    }

    /**
     * Setzt die Timer-Dauer und startet den Timer.
     * Gibt beim Start die aktuelle Uhrzeit per Sprachsynthese aus.
     */
    public void startTimer(int minutes) {
        timerTotalMinutes = minutes;
        prefsManager.saveTimerMinutes(minutes);

        stopTimerInternal();

        long millis = minutes * 60L * 1000L;
        timerMillisRemaining = millis;
        isTimerRunning = true;
        isFadingOut = false; // Fade-out-Zustand zurücksetzen

        Log.d(TAG, "Timer gestartet: " + minutes + " Minuten");


        sleepTimer = new CountDownTimer(millis, 1000) {
            @Override
            public void onTick(long millisUntilFinished) {
                timerMillisRemaining = millisUntilFinished;

                // === Fade-out Logik ===
                if (!isFadingOut && millisUntilFinished <= FADE_OUT_DURATION_MS) {
                    // Fade-out beginnt: Lautstärke für nächsten Start speichern
                    isFadingOut = true;
                    volumeBeforeFade = currentVolume;
                    prefsManager.saveVolume(VolumeHelper.volumeToProgress(currentVolume));
                    Log.d(TAG, "Fade-out gestartet. Lautstärke gespeichert: " + currentVolume);
                }
                if (isFadingOut && volumeBeforeFade > 0f) {
                    float fadeFactor = (float) millisUntilFinished / FADE_OUT_DURATION_MS;
                    float fadedVolume = effectiveVolume(volumeBeforeFade * fadeFactor);
                    if (mediaPlayer != null) {
                        mediaPlayer.setVolume(fadedVolume, fadedVolume);
                    }
                }

                if (callback != null) {
                    callback.onTimerTick(millisUntilFinished);
                }
            }

            @Override
            public void onFinish() {
                isTimerRunning = false;
                timerMillisRemaining = 0;
                isFadingOut = false;
                Log.d(TAG, "Sleep-Timer abgelaufen – pausiere Wiedergabe");

                // Lautstärke wiederherstellen BEVOR pausiert wird,
                // damit beim nächsten Resume nicht der Fade-out-Wert (~0) im Player steckt
                if (mediaPlayer != null) {
                    mediaPlayer.setVolume(effectiveVolume(currentVolume), effectiveVolume(currentVolume));
                }

                // Wiedergabe pausieren (nicht komplett stoppen)
                pausePlayback();

                if (callback != null) {
                    callback.onTimerFinished();
                }

                // *** KRITISCH: Foreground-Status BEIBEHALTEN ***
                // Statt stopForeground() zeigen wir eine spezielle "Schlafmodus"-Notification.
                // Nur so bleibt der Service als Foreground-Service am Leben und die
                // MediaSession empfängt weiterhin Kopfhörer-Tasten-Events – auch nach
                // langer Pause (z.B. nachts beim Wiedereinschlafen).
                // Der Nutzer kann die Notification wegwischen um den Service zu beenden.
                showSleepModeNotification();

                Log.d(TAG, "Service bleibt im Foreground (Sleep-Mode-Notification). "
                        + "Kopfhörertaste kann Wiedergabe jederzeit neu starten.");
            }
        };
        sleepTimer.start();
    }

    /**
     * Startet den Timer mit der aktuellen Dauer neu.
     */
    public void restartTimer() {
        startTimer(timerTotalMinutes);
    }

    // ===== Getter =====

    public boolean isPlaying() {
        return isPlaying;
    }

    public boolean isRandomMode() {
        return isRandomMode;
    }

    /**
     * Setzt den Wiedergabe-Modus.
     * @param random true = zufällig, false = in Listenreihenfolge
     */
    public void setRandomMode(boolean random) {
        this.isRandomMode = random;
        prefsManager.saveRandomMode(random);
        Log.d(TAG, "Wiedergabe-Modus: " + (random ? "Zufall" : "Reihenfolge"));
    }

    public TrackSelector.TrackInfo getCurrentTrack() {
        return currentTrack;
    }

    /** Aktuelle Wiedergabeposition in Millisekunden (0 wenn kein Track). */
    public int getCurrentPosition() {
        if (mediaPlayer != null) {
            try {
                return mediaPlayer.getCurrentPosition();
            } catch (IllegalStateException e) {
                return 0;
            }
        }
        return 0;
    }

    /** Gesamtdauer des aktuellen Tracks in Millisekunden (0 wenn kein Track). */
    public int getDuration() {
        if (mediaPlayer != null) {
            try {
                int d = mediaPlayer.getDuration();
                return d > 0 ? d : 0;
            } catch (IllegalStateException e) {
                return 0;
            }
        }
        return 0;
    }

    /** Springt zur angegebenen Position in Millisekunden. */
    public void seekTo(int positionMs) {
        if (mediaPlayer != null) {
            try {
                mediaPlayer.seekTo(positionMs);
                Log.d(TAG, "seekTo: " + positionMs + "ms");
            } catch (IllegalStateException e) {
                Log.w(TAG, "seekTo: IllegalStateException", e);
            }
        }
    }

    public long getTimerMillisRemaining() {
        return timerMillisRemaining;
    }

    public boolean isTimerRunning() {
        return isTimerRunning;
    }

    public int getTimerTotalMinutes() {
        return timerTotalMinutes;
    }

    public TrackSelector getTrackSelector() {
        return trackSelector;
    }

    public MediaSessionCompat getMediaSession() {
        return mediaSession;
    }

    // ===== Private Hilfsmethoden =====

    private void releaseMediaPlayer() {
        mainHandler.removeCallbacks(sectionalGainRunnable);
        if (mediaPlayer != null) {
            Log.d(TAG, "releaseMediaPlayer()");
            try {
                if (mediaPlayer.isPlaying()) {
                    mediaPlayer.stop();
                }
            } catch (IllegalStateException e) {
                Log.w(TAG, "IllegalStateException beim Stoppen des MediaPlayers", e);
            }
            try {
                mediaPlayer.release();
            } catch (Exception e) {
                Log.w(TAG, "Fehler beim Release des MediaPlayers", e);
            }
            mediaPlayer = null;
        }
    }

    private void stopTimerInternal() {
        if (sleepTimer != null) {
            sleepTimer.cancel();
            sleepTimer = null;
        }
        // Falls ein Fade-out lief, Lautstärke wiederherstellen
        if (isFadingOut && mediaPlayer != null) {
            mediaPlayer.setVolume(effectiveVolume(currentVolume), effectiveVolume(currentVolume));
        }
        isFadingOut = false;
        isTimerRunning = false;
    }

    private void abandonAudioFocus() {
        if (audioFocusRequest != null) {
            audioManager.abandonAudioFocusRequest(audioFocusRequest);
        }
    }

    private void onAudioFocusChange(int focusChange) {
        Log.d(TAG, "onAudioFocusChange: " + focusChange);
        switch (focusChange) {
            case AudioManager.AUDIOFOCUS_LOSS:
                // Dauerhafter Verlust → pausieren
                pausePlayback();
                break;
            case AudioManager.AUDIOFOCUS_LOSS_TRANSIENT:
                // Kurzer Verlust → pausieren
                pausePlayback();
                break;
            case AudioManager.AUDIOFOCUS_LOSS_TRANSIENT_CAN_DUCK:
                // Leiser machen
                if (mediaPlayer != null) {
                    mediaPlayer.setVolume(effectiveVolume(currentVolume) * 0.3f,
                            effectiveVolume(currentVolume) * 0.3f);
                }
                break;
            case AudioManager.AUDIOFOCUS_GAIN:
                // Focus zurück → Lautstärke wiederherstellen
                if (mediaPlayer != null) {
                    mediaPlayer.setVolume(effectiveVolume(currentVolume), effectiveVolume(currentVolume));
                }
                // Nicht automatisch fortsetzen – Nutzer schläft vielleicht
                break;
        }
    }

    private void updatePlaybackState(int state) {
        if (mediaSession == null) return;

        long position = 0;
        if (mediaPlayer != null) {
            try {
                position = mediaPlayer.getCurrentPosition();
            } catch (IllegalStateException e) {
                // Ignore
            }
        }

        PlaybackStateCompat.Builder builder = new PlaybackStateCompat.Builder()
                .setActions(
                        PlaybackStateCompat.ACTION_PLAY
                                | PlaybackStateCompat.ACTION_PAUSE
                                | PlaybackStateCompat.ACTION_PLAY_PAUSE
                                | PlaybackStateCompat.ACTION_STOP
                                | PlaybackStateCompat.ACTION_SKIP_TO_NEXT)
                .setState(state, position, 1.0f);

        mediaSession.setPlaybackState(builder.build());
    }

    private void updateMediaMetadata(TrackSelector.TrackInfo track) {
        if (mediaSession == null || track == null) return;

        MediaMetadataCompat metadata = new MediaMetadataCompat.Builder()
                .putString(MediaMetadataCompat.METADATA_KEY_TITLE, track.title)
                .putString(MediaMetadataCompat.METADATA_KEY_ARTIST, track.artist)
                .putString(MediaMetadataCompat.METADATA_KEY_ALBUM, track.album)
                .putLong(MediaMetadataCompat.METADATA_KEY_DURATION, track.duration)
                .build();

        mediaSession.setMetadata(metadata);
    }

    private void showNotification() {
        String title = currentTrack != null ? currentTrack.title : "SleepPlayer";
        Notification notification = NotificationHelper.buildNotification(
                this, mediaSession, title, isPlaying);
        startForeground(NotificationHelper.NOTIFICATION_ID, notification);
    }

    /**
     * Zeigt die "Schlafmodus"-Notification und hält den Service im Foreground.     * Wird aufgerufen wenn der Sleep-Timer abläuft und Wiedergabe pausiert wurde.
     * Hält die MediaSession aktiv → Kopfhörer-Tasten weiterhin nutzbar.
     */
    private void showSleepModeNotification() {
        String title = currentTrack != null ? currentTrack.title : "SleepPlayer";
        Notification notification = NotificationHelper.buildSleepNotification(
                this, mediaSession, title);
        // startForeground() hält den Service als Foreground-Service am Leben
        startForeground(NotificationHelper.NOTIFICATION_ID, notification);
        Log.d(TAG, "Sleep-Mode-Notification aktiv – Service bleibt im Foreground");
    }

    /**
     * Zeigt die Meditations-Notification und hält den Service im Foreground.
     */
    private void showMeditationNotification() {
        Notification notification = NotificationHelper.buildMeditationNotification(
                this, mediaSession,
                "Einatmen 4s · Halten 7s · Ausatmen 8s · Doppelklick = Ende");
        startForeground(NotificationHelper.NOTIFICATION_ID, notification);
        Log.d(TAG, "Meditations-Notification aktiv");
    }

    /** Acquiriert den Service-WakeLock (idempotent). */
    private void acquireServiceWakeLock() {        if (serviceWakeLock != null && !serviceWakeLock.isHeld()) {
            serviceWakeLock.acquire();
            Log.d(TAG, "Service-WakeLock acquired");
        }
    }

    /** Gibt den Service-WakeLock frei (idempotent). */
    private void releaseServiceWakeLock() {
        if (serviceWakeLock != null && serviceWakeLock.isHeld()) {
            serviceWakeLock.release();
            Log.d(TAG, "Service-WakeLock released");
        }
    }

    /**
     * Berechnet die effektive Lautstärke unter Berücksichtigung des Track-Gains.
     * Ergebnis ist immer im Bereich [0.0, 1.0].
     */
    private float effectiveVolume(float base) {
        return Math.max(0.0f, Math.min(1.0f, base * currentTrackGain));
    }

    /**
     * Liest die aktuelle Sektions-Gain und wendet sie auf den MediaPlayer an.
     * Wird periodisch durch sectionalGainRunnable aufgerufen.
     */
    private void applySectionalGain() {
        if (currentSectionalGains == null || mediaPlayer == null || !isPlaying) return;
        try {
            int posMs = mediaPlayer.getCurrentPosition();
            float sectionGain = findSectionGain(posMs);
            float vol = Math.max(0f, Math.min(1f, currentVolume * sectionGain));
            mediaPlayer.setVolume(vol, vol);
            Log.d(TAG, "Sektions-Gain bei " + posMs + "ms: " + sectionGain + "×");
        } catch (IllegalStateException e) {
            Log.w(TAG, "applySectionalGain: IllegalStateException", e);
        }
    }

    /**
     * Findet den passenden Sektions-Gain-Multiplier für eine gegebene Position.
     * Die Sektionen sind nach Startzeit sortiert gespeichert.
     */
    private float findSectionGain(int positionMs) {
        if (currentSectionalGains == null || currentSectionalGains.isEmpty()) return currentTrackGain;
        float gain = currentSectionalGains.get(0)[1];
        for (float[] section : currentSectionalGains) {
            if (section[0] <= positionMs) {
                gain = section[1];
            } else {
                break;
            }
        }
        return gain;
    }

    /** Gibt den NormalizationStore zurück (für die Activity). */
    public NormalizationStore getNormalizationStore() {
        return normalizationStore;
    }
}

package com.example.sleepplayer;

import android.content.Context;
import android.content.SharedPreferences;

import org.json.JSONArray;
import org.json.JSONException;

import java.util.ArrayList;
import java.util.List;

/**
 * Verwaltet App-Einstellungen über SharedPreferences.
 * Speichert: Lautstärke, Timer-Dauer, zuletzt gespielte Titel.
 */
public class PrefsManager {

    private static final String PREFS_NAME = "sleep_player_prefs";
    private static final String KEY_VOLUME = "volume_level";
    private static final String KEY_TIMER_MINUTES = "timer_minutes";
    private static final String KEY_RECENT_TRACKS = "recent_tracks";
    private static final String KEY_FOLDER_URI = "folder_uri";
    private static final String KEY_FOLDER_DISPLAY = "folder_display_name";
    private static final String KEY_RANDOM_MODE = "random_mode";
    private static final String KEY_TTS_ENABLED = "tts_enabled";
    private static final int MAX_RECENT = 5;

    private final SharedPreferences prefs;

    public PrefsManager(Context context) {
        prefs = context.getSharedPreferences(PREFS_NAME, Context.MODE_PRIVATE);
    }

    // --- Lautstärke ---

    /**
     * Speichert die Lautstärke-Position (SeekBar 0-200).
     */
    public void saveVolume(int volumeProgress) {
        prefs.edit().putInt(KEY_VOLUME, volumeProgress).apply();
    }

    /**
     * Gibt die gespeicherte Lautstärke-Position zurück (Standard: 30).
     */
    public int getVolume() {
        return prefs.getInt(KEY_VOLUME, 30);
    }

    // --- Timer ---

    /**
     * Speichert die Timer-Dauer in Minuten.
     */
    public void saveTimerMinutes(int minutes) {
        prefs.edit().putInt(KEY_TIMER_MINUTES, minutes).apply();
    }

    /**
     * Gibt die gespeicherte Timer-Dauer zurück (Standard: 30 Min).
     */
    public int getTimerMinutes() {
        return prefs.getInt(KEY_TIMER_MINUTES, 30);
    }

    // --- Ordner-Filter ---

    /**
     * Speichert den ausgewählten Ordner-URI (als String).
     * null = kein Filter (alle Audio-Dateien).
     */
    public void saveFolderUri(String uriString) {
        prefs.edit().putString(KEY_FOLDER_URI, uriString).apply();
    }

    /**
     * Gibt den gespeicherten Ordner-URI zurück (null = kein Filter).
     */
    public String getFolderUri() {
        return prefs.getString(KEY_FOLDER_URI, null);
    }

    /**
     * Speichert den Anzeigenamen des Ordners.
     */
    public void saveFolderDisplayName(String name) {
        prefs.edit().putString(KEY_FOLDER_DISPLAY, name).apply();
    }

    /**
     * Gibt den Anzeigenamen des Ordners zurück.
     */
    public String getFolderDisplayName() {
        return prefs.getString(KEY_FOLDER_DISPLAY, null);
    }

    /**
     * Löscht den Ordner-Filter (zurück zu "alle Dateien").
     */
    public void clearFolder() {
        prefs.edit()
                .remove(KEY_FOLDER_URI)
                .remove(KEY_FOLDER_DISPLAY)
                .apply();
    }

    // --- Zufallswiedergabe ---

    /** Speichert den Random-Modus (true = Zufall, false = Reihenfolge). */
    public void saveRandomMode(boolean random) {
        prefs.edit().putBoolean(KEY_RANDOM_MODE, random).apply();
    }

    /** Gibt zurück ob Zufallswiedergabe aktiv ist (Standard: true). */
    public boolean isRandomMode() {
        return prefs.getBoolean(KEY_RANDOM_MODE, true);
    }

    // --- Zeitansage (TTS) ---

    /** Speichert ob die Zeitansage aktiviert ist. */
    public void saveTtsEnabled(boolean enabled) {
        prefs.edit().putBoolean(KEY_TTS_ENABLED, enabled).apply();
    }

    /** Gibt zurück ob die Zeitansage aktiviert ist (Standard: true). */
    public boolean isTtsEnabled() {
        return prefs.getBoolean(KEY_TTS_ENABLED, true);
    }

    // --- Zuletzt gespielte Titel ---

    /**
     * Gibt die Liste der zuletzt gespielten Track-URIs zurück.
     */
    public List<String> getRecentTracks() {
        List<String> result = new ArrayList<>();
        String json = prefs.getString(KEY_RECENT_TRACKS, "[]");
        try {
            JSONArray arr = new JSONArray(json);
            for (int i = 0; i < arr.length(); i++) {
                result.add(arr.getString(i));
            }
        } catch (JSONException e) {
            // Ignore corrupt data
        }
        return result;
    }

    /**
     * Fügt einen Track zur Zuletzt-Gespielt-Liste hinzu.
     * Hält maximal MAX_RECENT Einträge (älteste werden entfernt).
     */
    public void addRecentTrack(String uri) {
        List<String> recent = getRecentTracks();
        // Entferne falls schon vorhanden
        recent.remove(uri);
        // Am Ende hinzufügen
        recent.add(uri);
        // Auf MAX_RECENT begrenzen
        while (recent.size() > MAX_RECENT) {
            recent.remove(0);
        }
        // Speichern
        JSONArray arr = new JSONArray(recent);
        prefs.edit().putString(KEY_RECENT_TRACKS, arr.toString()).apply();
    }
}

package com.example.sleepplayer;

import android.content.Context;
import android.content.SharedPreferences;

import org.json.JSONArray;
import org.json.JSONException;

import java.util.ArrayList;
import java.util.List;

/**
 * Verwaltet App-Einstellungen über SharedPreferences.
 * Speichert: Lautstärke, Timer-Dauer, zuletzt gespielte Titel.
 */
public class PrefsManager {

    private static final String PREFS_NAME = "sleep_player_prefs";
    private static final String KEY_VOLUME = "volume_level";
    private static final String KEY_TIMER_MINUTES = "timer_minutes";
    private static final String KEY_RECENT_TRACKS = "recent_tracks";
    private static final String KEY_FOLDER_URI = "folder_uri";
    private static final String KEY_FOLDER_DISPLAY = "folder_display_name";
    private static final String KEY_RANDOM_MODE = "random_mode";
    private static final String KEY_TTS_ENABLED = "tts_enabled";
    private static final String KEY_SECTION_LENGTH_SEC = "section_length_sec";
    private static final int MAX_RECENT = 5;

    private final SharedPreferences prefs;

    public PrefsManager(Context context) {
